const cr = (n) => {
  if (n >= 1e7) { const x = n / 1e7; return "₹" + (Number.isInteger(x) ? x : x.toFixed(2).replace(/\.?0+$/, "")) + " Cr"; }
  if (n >= 1e5) { const x = n / 1e5; return "₹" + (Number.isInteger(x) ? x : x.toFixed(1).replace(/\.0$/, "")) + " L"; }
  return "₹" + n.toLocaleString("en-IN");
};

function QR({ value = "MB", size = 112 }) {
  const n = 21, pad = 1, tot = n + pad * 2, cell = size / tot;
  let h = 2166136261; for (let i = 0; i < value.length; i++) { h ^= value.charCodeAt(i); h = Math.imul(h, 16777619); }
  const rnd = () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; h >>>= 0; return h / 4294967296; };
  const finder = (x, y) => (x < 7 && y < 7) || (x > n - 8 && y < 7) || (x < 7 && y > n - 8);
  const cells = [];
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { if (finder(x, y)) continue; if (rnd() > 0.52) cells.push([x, y]); }
  const eye = (ox, oy) => [[ox, oy, 7, 7, "#16345F"], [ox + 1, oy + 1, 5, 5, "#fff"], [ox + 2, oy + 2, 3, 3, "#16345F"]];
  const eyes = [...eye(0, 0), ...eye(n - 7, 0), ...eye(0, n - 7)];
  return (
    <svg width={size} height={size} style={{ background: "#fff", borderRadius: 8, display: "block" }} shapeRendering="crispEdges">
      {eyes.map(([x, y, w, hh, c], i) => <rect key={"e" + i} x={(x + pad) * cell} y={(y + pad) * cell} width={w * cell} height={hh * cell} fill={c} />)}
      {cells.map(([x, y], i) => <rect key={i} x={(x + pad) * cell} y={(y + pad) * cell} width={cell} height={cell} fill="#16345F" />)}
    </svg>
  );
}

function useIsMobile(bp = 760) {  const [m, setM] = useState(typeof window !== "undefined" ? window.innerWidth < bp : false);
  useEffect(() => { const f = () => setM(window.innerWidth < bp); window.addEventListener("resize", f); f(); return () => window.removeEventListener("resize", f); }, [bp]);
  return m;
}

