/* ---------------------------------------------------------------------------
   EDIT 1 of 5 (see legacy/PATCHES.md).

   The context now comes from ../proc/context.js instead of being created here.

   WHY: ProcProvider needs to put live server data into the SAME context object
   these screens read from. Two createContext() calls make two unrelated
   contexts, and the symptom is a useProc() that returns null and a screen that
   renders blank with no error at all.

   WAS:
     const ProcCtx = React.createContext(null);
     const useProc = () => React.useContext(ProcCtx);
--------------------------------------------------------------------------- */


let _pushToast = () => {};

export const toast = (msg, tone = "ink") => _pushToast(msg, tone);

/* EDIT 3 of 5: exported so the live app and ProcProvider can raise toasts. */
export function Toaster() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    _pushToast = (msg, tone) => { const id = Math.random().toString(36).slice(2); setItems(x => [...x, { id, msg, tone }]); setTimeout(() => setItems(x => x.filter(i => i.id !== id)), 2600); };
    return () => { _pushToast = () => {}; };
  }, []);
  return (
    <div style={{ position: "fixed", left: "50%", transform: "translateX(-50%)", bottom: 22, zIndex: 200, display: "flex", flexDirection: "column", gap: 8, alignItems: "center", pointerEvents: "none" }}>
      {items.map(i => { const bg = i.tone === "green" ? C.green : i.tone === "red" ? C.red : i.tone === "gold" ? C.goldDeep : C.inkDeep; const Icon = i.tone === "red" ? TriangleAlert : i.tone === "gold" ? Sparkles : Check; return (
        <div key={i.id} style={{ background: bg, color: "#fff", font: `600 13px ${sans}`, padding: "11px 16px", borderRadius: 10, boxShadow: "0 10px 30px rgba(0,0,0,.22)", display: "flex", alignItems: "center", gap: 8, maxWidth: 360 }}><Icon size={15} /> {i.msg}</div>
      ); })}
    </div>
  );
}

