function CastPanel({ tab, onClose }) {
  const mob = useIsMobile();
  const MONEY = ["expenses", "sales", "masters", "accounts", "cost", "tax", "overview"];
  const sensitive = MONEY.includes(tab);
  const [pick, setPick] = useState(null);
  const [stage, setStage] = useState("pick");
  const [approver, setApprover] = useState("P. Nair · Accounts Head");
  useEffect(() => {
    if (stage !== "waiting") return;
    const t = setTimeout(() => setStage("approved"), 2600);
    return () => clearTimeout(t);
  }, [stage]);
  const go = (tv) => {
    setPick(tv);
    if (sensitive) setStage("consent"); else { setStage("casting"); toast(`Casting to ${tv.name}`, "green"); }
  };
  return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
          <Share2 size={17} color={C.gold} /><Eyebrow>Cast this screen</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        {stage === "pick" && (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Put it on the big screen.</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Screens found on this network — LG and Samsung Smart View, Google Cast and AirPlay.</div>
          {sensitive && (
            <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: 11, marginBottom: 12, display: "flex", gap: 9, font: `12px ${sans}`, color: C.inkSoft }}>
              <Lock size={15} color={C.amber} style={{ flexShrink: 0 }} />
              <div><b style={{ color: C.inkDeep }}>This screen shows money.</b> Someone responsible has to approve before it goes on a television.</div>
            </div>
          )}
          {TVS.map((tv, i) => (
            <div key={tv.id} onClick={() => go(tv)} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 11, padding: "11px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}` }}>
              <div style={{ width: 34, height: 26, borderRadius: 4, border: `2px solid ${C.inkDeep}`, flexShrink: 0, background: C.paper }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ font: `600 13px ${sans}`, color: C.ink }}>{tv.name}</div>
                <div style={{ font: `11px ${sans}`, color: C.stone }}>{tv.room} · {tv.how}</div>
              </div>
              <ChevronRight size={16} color={C.stone} />
            </div>
          ))}
        </>)}

        {stage === "consent" && (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Who is approving this?</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Financial figures are about to appear on <b style={{ color: C.ink }}>{pick.name}</b> in {pick.room}. The approval and the time are logged.</div>
          <label style={{ ...lbl, fontSize: 9 }}>Ask</label>
          <select value={approver} onChange={e => setApprover(e.target.value)} style={{ ...sel, margin: "5px 0 12px" }}>
            {["P. Nair · Accounts Head", "R. Khanna · Purchase Manager", "Simran Kaur · HR Head", "Nitish Walia · Chairman"].map(x => <option key={x}>{x}</option>)}
          </select>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <GoldButton onClick={() => { setStage("waiting"); toast(`Approval sent to ${approver.split("·")[0].trim()}`, "gold"); }}>Ask for approval</GoldButton>
            <GoldButton ghost onClick={() => setStage("pick")}>Back</GoldButton>
          </div>
        </>)}

        {stage === "waiting" && (
          <div style={{ textAlign: "center", padding: "22px 0" }}>
            <div style={{ width: 34, height: 34, border: `3px solid ${C.gold}`, borderTopColor: "transparent", borderRadius: "50%", margin: "0 auto 14px", animation: "mbSpin .8s linear infinite" }} />
            <IntakeStyles />
            <div style={{ font: `600 14px ${sans}`, color: C.ink }}>Waiting for {approver.split("·")[0].trim()}</div>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 5 }}>A pop-up has gone to their app. Nothing appears on the television until they tap approve.</div>
          </div>
        )}

        {(stage === "approved" || stage === "casting") && (
          <div style={{ textAlign: "center", padding: "16px 0" }}>
            <div style={{ width: 40, height: 40, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={21} color={C.green} /></div>
            <h2 style={{ font: `400 20px ${serif}`, margin: "0 0 6px" }}>Now showing on {pick.name}</h2>
            <div style={{ font: `12px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 14 }}>
              {pick.room} · {pick.how}{stage === "approved" ? <><br />Approved by <b style={{ color: C.ink }}>{approver}</b> at {new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}</> : null}
            </div>
            <div style={{ display: "flex", gap: 9, justifyContent: "center", flexWrap: "wrap" }}>
              <GoldButton small ghost onClick={() => { toast("Stopped casting", "stone"); onClose(); }}>Stop casting</GoldButton>
              <GoldButton small onClick={onClose}>Done</GoldButton>
            </div>
          </div>
        )}
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 12 }}>Real Smart View, Google Cast and AirPlay handshakes are done by the device with the backend. The approval rule around them is real.</div>
      </div>
    </Overlay>
  );
}

function GateActivity({ compact }) {
  const mob = useIsMobile();
  const { gateLog, exports, registerExport } = useProc();
  const [openEntry, setOpenEntry] = useState(null);
  const [exp, setExp] = useState(false);
  const [only, setOnly] = useState("all");
  const denies = gateLog.filter(g => g.outcome === "deny");
  const rows = (only === "deny" ? denies : only === "permit" ? gateLog.filter(g => g.outcome === "permit") : gateLog).slice(0, compact ? 4 : 20);
  const byGuard = {};
  denies.forEach(g => { byGuard[g.guard] = (byGuard[g.guard] || 0) + 1; });
  return (
    <Card pad={mob ? 14 : 20} style={{ marginBottom: 16, borderColor: denies.length ? C.amber : C.line }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
        <ShieldCheck size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>What happened at the gate</span>
        {denies.length > 0 && <Pill tone="red">{denies.length} turned away</Pill>}
        <div style={{ marginLeft: "auto", display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
          <ExportButton onClick={() => setExp(true)} />
          {[["all", "Everything"], ["deny", "Turned away"], ["permit", "Let in"]].map(([k, l]) => (
            <button key={k} onClick={() => setOnly(k)} style={{ cursor: "pointer", border: `1px solid ${only === k ? C.gold : C.line}`, background: only === k ? C.goldTint : "#fff", color: only === k ? C.goldDeep : C.stone, borderRadius: 20, padding: "4px 10px", font: `600 11px ${sans}` }}>{l}</button>
          ))}
        </div>
      </div>
      {Object.keys(byGuard).length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 10 }}>
          {Object.entries(byGuard).map(([g, n]) => <Pill key={g} tone="stone">{g} turned away {n}</Pill>)}
        </div>
      )}
      {rows.length === 0 ? <div style={{ font: `12px ${sans}`, color: C.stone }}>Nothing logged yet.</div> : rows.map((g, i) => (
        <div key={g.id} style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}` }}>
          <div style={{ width: 28, height: 28, borderRadius: 8, flexShrink: 0, display: "grid", placeItems: "center", background: g.outcome === "permit" ? C.greenSoft : C.redSoft }}>
            {g.outcome === "permit" ? <Check size={15} color={C.green} /> : <X size={15} color={C.red} />}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
              <span style={{ font: `600 13px ${sans}`, color: C.ink }}>{g.label}</span>
              <Pill tone={g.outcome === "permit" ? "green" : "red"}>{g.outcome === "permit" ? "Let in" : "Turned away"}</Pill>
              {g.plate && <span style={{ font: `11px ${mono}`, color: C.stone }}>{g.plate}</span>}
            </div>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 3 }}>
              {g.guard} ({g.guardId}) at {g.post} · {fmtAgo(g.at)} · authorised by {g.who} · {g.ev} attachment{g.ev !== 1 ? "s" : ""}
            </div>
            {g.note && <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginTop: 3, fontStyle: "italic" }}>{g.note}</div>}
          </div>
          <GoldButton small ghost onClick={() => setOpenEntry(g)}>Open</GoldButton>
        </div>
      ))}
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Every decision a guard makes is written here the moment he makes it — including the ones he turns away.</div>
      {exp && <ExportPanel userKey="admin" title="Gate activity" filterNote={only === "deny" ? "turned away only" : only === "permit" ? "let in only" : ""}
        cols={["Entry", "Outcome", "What", "Vehicle", "Guard", "Post", "Authorised by", "Attachments", "Note"]}
        rows={rows.map(g => [g.id, g.outcome === "permit" ? "Let in" : "Turned away", g.label, g.plate || "—", `${g.guard} (${g.guardId})`, g.post, g.who, g.ev, g.note || ""])}
        trail={rows.slice(0, 8).map(g => [g.id, `${g.outcome === "permit" ? "Permitted" : "Turned away"} at ${g.post}`, g.guard, fmtAgo(g.at)])}
        registry={exports} onRegister={registerExport} onClose={() => setExp(false)} />}
      {openEntry && <FilePreview title={openEntry.label} meta={openEntry.id} onClose={() => setOpenEntry(null)} lines={[["Outcome", openEntry.outcome === "permit" ? "Let in" : "Turned away"], ["Vehicle", openEntry.plate || "—"], ["Guard", `${openEntry.guard} (${openEntry.guardId})`], ["Post", openEntry.post], ["Authorised by", openEntry.who], ["Attachments", `${openEntry.ev} photo/voice`], ["Guard's note", openEntry.note || "—"], ["Logged", fmtAgo(openEntry.at)]]} />}
    </Card>
  );
}

