const PLATE_RE = /^[A-Z]{2}\s?\d{1,2}\s?[A-Z]{1,3}\s?\d{4}$/;

const normPlate = (p) => String(p || "").toUpperCase().replace(/[^A-Z0-9]/g, "");

function knownVehicles() {
  const out = [];
  POS.forEach(p => { const w = p.del && p.del.who; if (w) { const m = String(w).match(/[A-Z]{2}[- ]?\d{1,2}[- ]?[A-Z]{1,3}[- ]?\d{4}/); if (m) out.push({ plate: normPlate(m[0]), vendor: p.vendor, driver: String(w).split("·")[0].trim() }); } });
  return out;
}

function ScanGate({ pass, walkin, guard, onClose, onDone }) {
  const mob = useIsMobile(); const { activeFirm, logGate } = useProc();
  const [stage, setStage] = useState(walkin ? "story" : "scan");
  const [found, setFound] = useState(walkin ? null : null);
  const [ev, setEv] = useState([]);
  const [shots, setShots] = useState([]);
  const [who, setWho] = useState(AUTHORISERS[1]);
  const [note, setNote] = useState("");
  const [outcome, setOutcome] = useState(null);
  const cell = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };
  const doScan = () => { setFound(pass || null); setStage("story"); toast("Gate pass read", "green"); };
  const decide = (kind) => {
    if (kind === "permit" && shots.length < 2) return toast("Finish both photos — the driver and the number plate", "amber");
    if (kind === "permit" && !(shots[0] && shots[0].plateOk)) return toast("Type the vehicle number from the plate before permitting", "amber");
    setOutcome(kind); setStage("done");
    logGate({ outcome: kind, label: found ? `${found.vendor} · ${found.po}` : "Walk-in — no appointment", plate: (shots[0] && shots[0].plate) || "", guard: guard.name, guardId: guard.id, post: guard.post, who, ev: shots.length + ev.length, note });
    onDone && onDone(kind);
    toast(kind === "permit" ? "Delivery permitted — logged" : "Turned away — logged", kind === "permit" ? "green" : "red");
  };
  const Row = ({ k, v }) => (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "7px 0", borderTop: `1px solid ${C.lineSoft}`, font: `12px ${sans}` }}>
      <span style={{ color: C.stone }}>{k}</span><span style={{ color: C.ink, fontWeight: 600, textAlign: "right", maxWidth: "62%" }}>{v || "—"}</span>
    </div>
  );

  if (stage === "done") return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 20 : 26, textAlign: "center" }}>
        <div style={{ width: 42, height: 42, borderRadius: "50%", background: outcome === "permit" ? C.greenSoft : C.redSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}>
          {outcome === "permit" ? <Check size={22} color={C.green} /> : <X size={22} color={C.red} />}
        </div>
        <h2 style={{ font: `400 21px ${serif}`, margin: "0 0 6px" }}>{outcome === "permit" ? "Delivery permitted" : "Turned away at the gate"}</h2>
        <div style={{ font: `13px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 14 }}>
          {found ? `${found.vendor} · ${found.po}` : "Walk-in"} · decided by <b style={{ color: C.ink }}>{guard.name}</b> at {guard.post}.<br />
          Authorised by <b style={{ color: C.ink }}>{who}</b> · {shots.length} photo{shots.length !== 1 ? "s" : ""}{ev.length ? ` + ${ev.length} more` : ""} on the entry.<br />
          <span style={{ font: `11px ${mono}`, color: C.stone }}>{shots[0] && shots[0].plate ? `Vehicle ${shots[0].plate} · ` : ""}{guard.id} · {new Date().toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })} · {new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}</span>
        </div>
        <GoldButton small onClick={onClose}>Done</GoldButton>
      </div>
    </Overlay>
  );

  return (
    <Overlay onClose={onClose} width={560}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <ScanLine size={18} color={C.gold} /><Eyebrow>Gate check</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        {stage === "scan" && (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{ width: 132, height: 132, margin: "0 auto 14px", border: `2px dashed ${C.gold}`, borderRadius: 16, display: "grid", placeItems: "center", background: C.goldTint }}>
              <ScanLine size={44} color={C.goldDeep} />
            </div>
            <div style={{ font: `13px ${sans}`, color: C.inkSoft, marginBottom: 14 }}>Hold the driver's gate pass in front of the camera.</div>
            <GoldButton onClick={doScan}>Scan the pass</GoldButton>
            <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 12 }}>Camera reading comes with the backend — this reads the pass on file.</div>
          </div>
        )}

        {stage === "story" && (<>
          {found ? (<>
            <div style={{ background: C.greenSoft, border: `1px solid ${C.green}`, borderRadius: 10, padding: "9px 12px", font: `12px ${sans}`, color: C.ink, marginBottom: 12, display: "flex", alignItems: "center", gap: 8 }}>
              <ShieldCheck size={15} color={C.green} /> Valid pass, issued by the app.
            </div>
            <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12, padding: 14, marginBottom: 12 }}>
              <div style={{ font: `600 14px ${sans}`, color: C.inkDeep, marginBottom: 2 }}>{found.vendor}</div>
              <div style={{ font: `12px ${sans}`, color: C.stone }}>{found.items}</div>
              <Row k="Purchase order" v={found.po} />
              <Row k="Order value" v={found.total ? inr(found.total) : "—"} />
              <Row k="Raised by" v={found.by} />
              <Row k="Sent to gate" v={fmtAgo(found.at) || "—"} />
              <Row k="Post" v={guard.post} />
            </div>
          </>) : (
            <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: "10px 12px", font: `12px ${sans}`, color: C.inkSoft, marginBottom: 12, display: "flex", gap: 8 }}>
              <TriangleAlert size={15} color={C.amber} style={{ flexShrink: 0 }} /><div><b>No appointment on record.</b> Nothing was sent to this gate for this vehicle. Speak to the office before letting anyone in.</div>
            </div>
          )}

          <label style={{ ...lbl, fontSize: 9 }}>Who allowed it? <span style={{ textTransform: "none", letterSpacing: 0, color: C.stone, fontWeight: 400 }}>· the name goes on the entry</span></label>
          <select value={who} onChange={e => setWho(e.target.value)} style={{ ...sel, margin: "5px 0 10px" }}>{AUTHORISERS.map(a => <option key={a}>{a}</option>)}</select>

          <label style={{ ...lbl, fontSize: 9 }}>Take the two photos</label>
          <div style={{ marginTop: 6, marginBottom: 10 }}><GateCapture guard={guard} shots={shots} setShots={setShots} /></div>
          <label style={{ ...lbl, fontSize: 9 }}>Anything else? <span style={{ textTransform: "none", letterSpacing: 0, color: C.stone, fontWeight: 400 }}>· optional</span></label>
          <div style={{ marginTop: 6, marginBottom: 10 }}><EvidenceRow ev={ev} setEv={setEv} /></div>

          <label style={{ ...lbl, fontSize: 9 }}>Note</label>
          <textarea value={note} onChange={e => setNote(e.target.value)} rows={2} placeholder="Vehicle number, driver name, anything unusual" style={{ ...cell, marginTop: 5, resize: "vertical" }} />

          <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
            <GreenButton onClick={() => decide("permit")}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Check size={14} /> Permit the delivery</span></GreenButton>
            <GoldButton ghost onClick={() => decide("deny")}>Turn away</GoldButton>
            <GoldButton ghost small onClick={() => toast(`Calling the office…`)}><span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><Phone size={13} /> Call office</span></GoldButton>
          </div>
          <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Nothing is permitted until both photos are taken. Every photo is stamped with your post, the date and the time.</div>
        </>)}
      </div>
    </Overlay>
  );
}

