function saleMath(s) {
  const plan = PAY_PLANS[s.plan] || PAY_PLANS["Grand · standard"];
  const reached = BUILD_STAGE[s.tower] || 1;
  let cum = 0;
  const rows = plan.stages.map((st, i) => {
    const amt = Math.round(s.price * st[1] / 100);
    const due = i < reached;
    if (due) cum += amt;
    return { name: st[0], pct: st[1], amt, due, i };
  });
  const billed = cum;
  const outstanding = Math.max(0, billed - s.paid);
  const nextIdx = rows.findIndex(r => !r.due);
  const next = nextIdx >= 0 ? rows[nextIdx] : null;
  const future = rows.filter(r => !r.due).reduce((a, r) => a + r.amt, 0);
  return { plan, rows, billed, outstanding, next, future, pctPaid: Math.round(s.paid / s.price * 100) };
}

