function AddBuyer({ onClose, onAdd }) {
  const mob = useIsMobile(); const { firms } = useProc();
  const [f, setF] = useState({ buyer: "", phone: "", email: "", unit: "", tower: Object.keys(BUILD_STAGE)[0], proj: "Marbella Royce",
    firm: firms[0] ? firms[0].firm : "", plan: Object.keys(PAY_PLANS)[0], price: "", booked: "", paid: "", auto: true, cadence: "Every 15 days until paid", lead: "7 days before the stage falls due" });
  const set = (k, v) => setF(s => ({ ...s, [k]: v }));
  const cell = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };
  const L = ({ children }) => <label style={{ ...lbl, fontSize: 9 }}>{children}</label>;
  const two = { display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 };
  const save = () => {
    if (!f.buyer.trim() || !f.unit.trim()) return toast("Name and apartment are needed", "amber");
    if (!f.price) return toast("Add the agreed price", "amber");
    onAdd({ ...f, id: "SL-" + (2050 + Math.floor(Math.random() * 90)), price: Number(f.price), paid: Number(f.paid || 0) });
    toast(`${f.buyer} added${f.auto ? " · reminders will run automatically" : ""}`, "green"); onClose();
  };
  return (
    <Overlay onClose={onClose} width={640}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <UserPlus size={17} color={C.gold} /><Eyebrow>Add a buyer</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Who has bought, and on what plan.</h2>
        <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>Once the plan is set, the app works out every instalment for you and can chase it on its own.</div>
        <div style={two}>
          <div><L>Buyer's name *</L><input value={f.buyer} onChange={e => set("buyer", e.target.value)} placeholder="e.g. Aman Gill" style={{ ...cell, marginTop: 5 }} /></div>
          <div style={{ marginTop: mob ? 10 : 0 }}><L>Apartment *</L><input value={f.unit} onChange={e => set("unit", e.target.value)} placeholder="e.g. B-1204" style={{ ...cell, marginTop: 5 }} /></div>
        </div>
        <div style={two}>
          <div><L>Phone</L><input value={f.phone} onChange={e => set("phone", e.target.value)} placeholder="+91 …" style={{ ...cell, marginTop: 5 }} /></div>
          <div style={{ marginTop: mob ? 10 : 0 }}><L>Email</L><input value={f.email} onChange={e => set("email", e.target.value)} placeholder="name@gmail.com" style={{ ...cell, marginTop: 5 }} /></div>
        </div>
        <div style={two}>
          <div><L>Tower</L><select value={f.tower} onChange={e => set("tower", e.target.value)} style={{ ...sel, margin: "5px 0 0" }}>{Object.keys(BUILD_STAGE).map(t => <option key={t}>{t}</option>)}</select></div>
          <div style={{ marginTop: mob ? 10 : 0 }}><L>Firm</L><select value={f.firm} onChange={e => set("firm", e.target.value)} style={{ ...sel, margin: "5px 0 0" }}>{[...new Set(COMPANIES_SEED.filter(c => c.kind === "Own firm").map(c => c.name))].map(n => <option key={n}>{n}</option>)}</select></div>
        </div>
        <L>Payment plan</L>
        <select value={f.plan} onChange={e => set("plan", e.target.value)} style={{ ...sel, margin: "5px 0 4px" }}>{Object.keys(PAY_PLANS).map(p => <option key={p}>{p}</option>)}</select>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginBottom: 10 }}>{(PAY_PLANS[f.plan] || {}).stages ? PAY_PLANS[f.plan].stages.map(s => `${s[1]}% ${s[0]}`).join(" · ") : ""}</div>
        <div style={two}>
          <div><L>Agreed price *</L><input value={f.price} onChange={e => set("price", e.target.value.replace(/[^\d]/g, ""))} placeholder="e.g. 14200000" style={{ ...cell, marginTop: 5, fontFamily: mono }} />{f.price ? <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 4 }}>{inr(Number(f.price))} · {wordsIN(Number(f.price))}</div> : null}</div>
          <div style={{ marginTop: mob ? 10 : 0 }}><L>Received so far</L><input value={f.paid} onChange={e => set("paid", e.target.value.replace(/[^\d]/g, ""))} placeholder="0" style={{ ...cell, marginTop: 5, fontFamily: mono }} /></div>
        </div>
        <L>Booked on</L>
        <input value={f.booked} onChange={e => set("booked", e.target.value)} placeholder="e.g. 18 Apr 2025" style={{ ...cell, margin: "5px 0 12px" }} />
        <div style={{ background: f.auto ? C.goldTint : C.paper, border: `1px solid ${f.auto ? C.gold : C.line}`, borderRadius: 11, padding: 12 }}>
          <label style={{ display: "flex", alignItems: "center", gap: 9, cursor: "pointer", font: `600 13px ${sans}`, color: C.inkDeep }}>
            <input type="checkbox" checked={f.auto} onChange={e => set("auto", e.target.checked)} /> Chase this buyer automatically
          </label>
          {f.auto && (<>
            <div style={{ marginTop: 10 }}><L>Start reminding</L>
              <select value={f.lead} onChange={e => set("lead", e.target.value)} style={{ ...sel, margin: "5px 0 8px" }}>
                {["On the day the stage falls due", "7 days before the stage falls due", "15 days before the stage falls due"].map(x => <option key={x}>{x}</option>)}
              </select></div>
            <L>Then repeat</L>
            <select value={f.cadence} onChange={e => set("cadence", e.target.value)} style={{ ...sel, margin: "5px 0 0" }}>
              {["Every 7 days until paid", "Every 15 days until paid", "Once a month until paid", "Do not repeat"].map(x => <option key={x}>{x}</option>)}
            </select>
            <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 8 }}>Every automatic reminder still waits for the Chairman's approval before it leaves.</div>
          </>)}
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
          <GoldButton onClick={save}>Add the buyer</GoldButton>
          <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
        </div>
      </div>
    </Overlay>
  );
}

function RaisePayment({ onClose, onQueue }) {
  const mob = useIsMobile(); const { activeFirm } = useProc();
  const [f, setF] = useState({ who: "A buyer", name: "", phone: "", email: "", amt: "", what: "", by: "", ch: { e: true, w: true } });
  const set = (k, v) => setF(s => ({ ...s, [k]: v }));
  const cell = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };
  const L = ({ children }) => <label style={{ ...lbl, fontSize: 9 }}>{children}</label>;
  const [body, setBody] = useState("");
  const [stage, setStage] = useState("who");
  const draft = () => {
    if (!f.name.trim()) return toast("Who is it going to?", "amber");
    if (!f.amt) return toast("How much?", "amber");
    setBody(`Dear ${f.name},

Warm greetings from Marbella Group.

This is with reference to ${f.what || "the amount due to us"}.

Amount    : ${inr(Number(f.amt))}
Due by    : ${f.by || "at the earliest"}
Reference : ${activeFirm.name}

We request you to kindly arrange the payment. If it has already been made, please share the transaction details so we may update our records.

We are grateful for your association with Marbella.

Warm regards,
Accounts — ${activeFirm.firm}
GSTIN ${activeFirm.gstin}`);
    setStage("draft");
  };
  return (
    <Overlay onClose={onClose} width={620}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <Send size={17} color={C.gold} /><Eyebrow>Raise a payment</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        {stage === "who" ? (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Ask anybody for money owed.</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>A buyer, a company, a contractor, a tenant — anyone. Write it once and it goes out on our letterhead.</div>
          <L>Who is it?</L>
          <div style={{ display: "flex", gap: 7, margin: "6px 0 12px", flexWrap: "wrap" }}>
            {["A buyer", "A company", "A contractor", "Someone else"].map(x => (
              <button key={x} onClick={() => set("who", x)} style={{ cursor: "pointer", border: `1px solid ${f.who === x ? C.gold : C.line}`, background: f.who === x ? C.goldTint : "#fff", color: f.who === x ? C.goldDeep : C.stone, borderRadius: 20, padding: "7px 13px", font: `600 11px ${sans}` }}>{x}</button>
            ))}
          </div>
          <L>Name *</L>
          <input value={f.name} onChange={e => set("name", e.target.value)} placeholder="Person or company" style={{ ...cell, margin: "5px 0 10px" }} />
          <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
            <div><L>Phone</L><input value={f.phone} onChange={e => set("phone", e.target.value)} placeholder="+91 …" style={{ ...cell, marginTop: 5, marginBottom: mob ? 8 : 0 }} /></div>
            <div><L>Email</L><input value={f.email} onChange={e => set("email", e.target.value)} placeholder="name@company.in" style={{ ...cell, marginTop: 5 }} /></div>
          </div>
          <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
            <div><L>Amount *</L><input value={f.amt} onChange={e => set("amt", e.target.value.replace(/[^\d]/g, ""))} placeholder="e.g. 250000" style={{ ...cell, marginTop: 5, fontFamily: mono, marginBottom: mob ? 8 : 0 }} />{f.amt ? <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 4 }}>{inr(Number(f.amt))}</div> : null}</div>
            <div><L>Wanted by</L><input value={f.by} onChange={e => set("by", e.target.value)} placeholder="e.g. 20 Aug 2026" style={{ ...cell, marginTop: 5 }} /></div>
          </div>
          <L>What is it for?</L>
          <textarea value={f.what} onChange={e => set("what", e.target.value)} rows={2} placeholder="e.g. balance against the sale of unit B-1204 / hire charges for July / security deposit refund" style={{ ...cell, marginTop: 5, resize: "vertical" }} />
          <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
            <GoldButton onClick={draft}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>Write the letter <ArrowRight size={14} /></span></GoldButton>
            <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
          </div>
        </>) : (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>To {f.name} · {inr(Number(f.amt))}</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Edit anything. It leaves only after the Chairman approves it.</div>
          <div style={{ display: "flex", gap: 12, marginBottom: 10, flexWrap: "wrap" }}>
            <label style={{ display: "flex", alignItems: "center", gap: 7, font: `12px ${sans}`, color: C.inkSoft }}><input type="checkbox" checked={f.ch.e} onChange={e => set("ch", { ...f.ch, e: e.target.checked })} /> Email {f.email || "—"}</label>
            <label style={{ display: "flex", alignItems: "center", gap: 7, font: `12px ${sans}`, color: C.inkSoft }}><input type="checkbox" checked={f.ch.w} onChange={e => set("ch", { ...f.ch, w: e.target.checked })} /> WhatsApp {f.phone || "—"}</label>
          </div>
          <textarea value={body} onChange={e => setBody(e.target.value)} rows={mob ? 10 : 13} style={{ ...cell, resize: "vertical", lineHeight: 1.6 }} />
          <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
            <GoldButton onClick={() => { onQueue({ sale: "—", buyer: f.name, unit: f.who, amt: Number(f.amt), when: f.by || "on approval", subj: `Payment request — ${activeFirm.name}`, body, ch: [f.ch.e && "Email", f.ch.w && "WhatsApp"].filter(Boolean).join(" + ") }); }}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><ShieldCheck size={14} /> Send for the Chairman's approval</span>
            </GoldButton>
            <GoldButton ghost onClick={() => setStage("who")}>Back</GoldButton>
          </div>
        </>)}
      </div>
    </Overlay>
  );
}

const MONTHS12 = ["Sep 25", "Oct 25", "Nov 25", "Dec 25", "Jan 26", "Feb 26", "Mar 26", "Apr 26", "May 26", "Jun 26", "Jul 26", "Aug 26"];

function StatementCoverage() {
  const mob = useIsMobile();
  const { firms, activeFirm } = useProc();
  const [firm, setFirm] = useState(activeFirm.name);
  const [have, setHave] = useState(() => MONTHS12.map((_, i) => i < 4 || i > 6));
  const missing = MONTHS12.filter((_, i) => !have[i]);
  const first = MONTHS12[have.findIndex(Boolean)];
  const last = MONTHS12[have.lastIndexOf(true)];
  return (
    <Card pad={mob ? 14 : 20} style={{ marginBottom: 16, borderColor: missing.length ? C.amber : C.line }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, flexWrap: "wrap" }}>
        <Calendar size={15} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>What we hold to reconcile against</span>
        <select value={firm} onChange={e => setFirm(e.target.value)} style={{ ...sel, margin: 0, width: mob ? "100%" : 220, padding: "6px 9px", fontSize: 12, marginLeft: mob ? 0 : "auto", marginTop: mob ? 8 : 0 }}>
          {firms.map(f => <option key={f.id}>{f.name}</option>)}
        </select>
      </div>
      <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginBottom: 10 }}>
        For <b style={{ color: C.ink }}>{firm}</b> we have bank statements from <b style={{ color: C.ink }}>{first}</b> to <b style={{ color: C.ink }}>{last}</b>.
        {missing.length > 0 ? <> <span style={{ color: C.amber, fontWeight: 600 }}>{missing.length} months are missing</span> — reconciliation for that period cannot be trusted until they are uploaded.</> : " Nothing is missing."}
      </div>
      <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 10 }}>
        {MONTHS12.map((mth, i) => (
          <div key={mth} title={have[i] ? "on file" : "missing"} style={{ flex: "1 0 62px", textAlign: "center", padding: "7px 4px", borderRadius: 8, font: `600 10px ${sans}`,
            background: have[i] ? C.greenSoft : C.amberSoft, color: have[i] ? C.green : C.amber, border: `1px solid ${have[i] ? C.green : C.amber}` }}>
            {mth}<div style={{ font: `9px ${sans}`, opacity: .85, marginTop: 2 }}>{have[i] ? "on file" : "missing"}</div>
          </div>
        ))}
      </div>
      {missing.length > 0 && (
        <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: 11, display: "flex", gap: 9, alignItems: "center", flexWrap: "wrap" }}>
          <TriangleAlert size={15} color={C.amber} style={{ flexShrink: 0 }} />
          <span style={{ flex: 1, minWidth: 170, font: `12px ${sans}`, color: C.inkSoft }}>Upload the statements for <b>{missing.join(", ")}</b> and the gap closes itself.</span>
          <label style={{ ...softBtn, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6, font: `600 11px ${sans}` }}><Upload size={13} /> Upload the missing months
            <input type="file" multiple onChange={e => { if (e.target.files.length) { setHave(MONTHS12.map(() => true)); toast(`${e.target.files.length} statement file(s) read — the period is now complete`, "green"); } }} style={{ display: "none" }} />
          </label>
        </div>
      )}
      <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginTop: 10, font: `11px ${sans}`, color: C.stone }}>
        <Info size={13} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} />
        Statements are kept live for two years. After that the app asks whether to keep them as they are or compress and archive them.
      </div>
    </Card>
  );
}

function CashPulse() {
  const mob = useIsMobile();
  const inTot = SALES_SEED.reduce((a, s) => a + s.paid, 0);
  const outTot = EXP_SEED.reduce((a, e) => a + e.amt, 0);
  const dueNow = SALES_SEED.reduce((a, s) => a + saleMath(s).outstanding, 0);
  const pipeline = SALES_SEED.reduce((a, s) => a + saleMath(s).future, 0);
  const net = inTot - outTot;
  const max = Math.max(inTot, outTot) || 1;
  return (
    <Card pad={mob ? 16 : 20} style={{ marginBottom: 16, borderColor: C.goldSoft }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <TrendingUp size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Money in, money out</span><Pill tone="green">live</Pill>
      </div>
      {[["Money in — from buyers", inTot, C.green], ["Money out — all expenses", outTot, C.red]].map(([k, v, col]) => (
        <div key={k} style={{ marginBottom: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", font: `12px ${sans}`, color: C.inkSoft, marginBottom: 4 }}>
            <span>{k}</span><span style={{ font: `13px ${mono}`, color: col, fontWeight: 600 }}>{inr(v)}</span>
          </div>
          <div style={{ height: 9, background: C.lineSoft, borderRadius: 20, overflow: "hidden" }}>
            <div style={{ width: `${(v / max) * 100}%`, height: "100%", background: col, transition: "width .6s" }} />
          </div>
        </div>
      ))}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "10px 0 12px", borderTop: `2px solid ${C.gold}`, marginTop: 4 }}>
        <span style={{ font: `600 12px ${sans}`, color: C.inkDeep }}>Net position</span>
        <span style={{ font: `400 22px ${serif}`, color: net >= 0 ? C.green : C.red }}>{net >= 0 ? "+" : "−"}{inr(Math.abs(net))}</span>
      </div>
      <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        <div style={{ background: C.redSoft, border: `1px solid ${C.red}`, borderRadius: 10, padding: 11, marginBottom: mob ? 8 : 0 }}>
          <div style={{ font: `11px ${sans}`, color: C.stone }}>Owed to us today</div>
          <div style={{ font: `600 16px ${sans}`, color: C.red, marginTop: 3 }}>{inr(dueNow)}</div>
          <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 2 }}>billed to buyers, not yet received</div>
        </div>
        <div style={{ background: C.goldTint, border: `1px solid ${C.goldSoft}`, borderRadius: 10, padding: 11 }}>
          <div style={{ font: `11px ${sans}`, color: C.stone }}>Still to come — forecast</div>
          <div style={{ font: `600 16px ${sans}`, color: C.goldDeep, marginTop: 3 }}>{inr(pipeline)}</div>
          <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 2 }}>as the towers reach each stage</div>
        </div>
      </div>
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Forecast is built from the payment plan each buyer signed and how far their tower has actually got — not a guess.</div>
    </Card>
  );
}

function ExpenseDetail({ r, onClose }) {
  const mob = useIsMobile(); const { activeFirm, moves, gateLog } = useProc();
  const po = POS.find(p => r.src && r.src.includes(p.id));
  const vend = VENDORS.find(v => r.party && r.party.toLowerCase().includes(v.name.toLowerCase().split(" ")[0]));
  const mv = moves.find(m => po && m.ref === po.id);
  const [file, setFile] = useState(false);
  const Row = ({ k, v, tone }) => (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "7px 0", borderTop: `1px solid ${C.lineSoft}`, font: `12px ${sans}` }}>
      <span style={{ color: C.stone }}>{k}</span><span style={{ color: tone || C.ink, fontWeight: 600, textAlign: "right", maxWidth: "62%" }}>{v || "—"}</span>
    </div>
  );
  /* the trail behind this one line */
  const trail = [];
  if (po) {
    trail.push(["Purchase order raised", `${po.id} — ${po.item}`, "R. Khanna · Purchase", po.del ? "before delivery" : "—"]);
    if (po.del) {
      trail.push(["Reached the gate", `${po.del.who}`, "Security", po.del.at]);
      trail.push(["Taken into store", `Ordered ${po.del.exp} · received ${po.del.got}`, po.del.by, po.del.at]);
      if (po.del.flag === "short") trail.push(["Flagged short", po.del.note, "The app", po.del.at]);
      if (po.del.flag === "over") trail.push(["Flagged over-supply", po.del.note, "The app", po.del.at]);
    }
  }
  if (mv) trail.push(["Stock updated", `${mv.qty} ${mv.unit} of ${mv.item}${mv.bill ? ` · bill ${mv.bill}` : ""}`, mv.who, fmtAgo(mv.at)]);
  trail.push(["Filed to the ledger", `Under ${r.cat}, charged to ${r.dept}`, r.how === "scan" ? "Read by the app" : "Accounts", r.date]);

  return (
    <Overlay onClose={onClose} width={680}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
          <FileText size={17} color={C.gold} /><Eyebrow>Expense entry</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <DocHead firm={activeFirm} title={r.party} docId={r.id} compact />

        <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap", marginBottom: 10 }}>
          <span style={{ font: `400 30px ${serif}`, color: C.inkDeep }}>{inr(r.amt)}</span>
          <span style={{ font: `12px ${sans}`, color: C.stone }}>{wordsIN(r.amt)}</span>
        </div>

        <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 11, padding: 12 }}>
            <div style={{ font: `600 10px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.stone, marginBottom: 4 }}>The entry</div>
            <Row k="Head of expense" v={r.cat} />
            <Row k="Charged to" v={r.dept} />
            <Row k="Paid to" v={r.party} />
            <Row k="Date" v={r.date} />
            <Row k="Came from" v={`${HOW_ICON[r.how] || "📄"} ${r.src}`} />
            <Row k="Reference" v={r.id} />
          </div>
          <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 11, padding: 12, marginTop: mob ? 10 : 0 }}>
            <div style={{ font: `600 10px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.stone, marginBottom: 4 }}>Behind it</div>
            {po ? (<>
              <Row k="Purchase order" v={po.id} />
              <Row k="Order value" v={inr(po.amt)} />
              <Row k="Status" v={po.status} />
              {po.del && <Row k="Delivered" v={`${po.del.got} of ${po.del.exp}`} tone={po.del.flag === "ok" ? C.green : C.red} />}
              {po.del && po.del.gap ? <Row k="Difference" v={`${po.del.gap < 0 ? "−" : "+"}${inr(Math.abs(po.del.gap))}`} tone={po.del.gap < 0 ? C.red : C.amber} /> : null}
            </>) : vend ? (<>
              <Row k="Vendor" v={vend.name} />
              <Row k="Vendor code" v={vend.code} />
              <Row k="No order on file" v="paid directly" tone={C.amber} />
            </>) : <div style={{ font: `12px ${sans}`, color: C.stone, paddingTop: 6 }}>No purchase order behind this one — it is a direct expense.</div>}
          </div>
        </div>

        <div style={{ font: `600 10px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.goldDeep, margin: "14px 0 6px" }}>The trail</div>
        {trail.map((t, i) => (
          <div key={i} style={{ display: "flex", gap: 10, padding: "9px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}` }}>
            <div style={{ width: 20, height: 20, borderRadius: "50%", background: C.goldTint, border: `1px solid ${C.goldSoft}`, display: "grid", placeItems: "center", flexShrink: 0, font: `600 9px ${sans}`, color: C.goldDeep, marginTop: 1 }}>{i + 1}</div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ font: `600 12px ${sans}`, color: C.ink }}>{t[0]}</div>
              <div style={{ font: `11px ${sans}`, color: C.inkSoft, marginTop: 2 }}>{t[1]}</div>
              <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 2 }}>{t[2]} · {t[3]}</div>
            </div>
          </div>
        ))}

        <div style={{ display: "flex", gap: 9, marginTop: 14, flexWrap: "wrap" }}>
          <GoldButton small onClick={() => setFile(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><FileText size={13} /> Open the document</span></GoldButton>
          <GoldButton small ghost onClick={() => { downloadFile(`Marbella-${r.id}.csv`, ["MARBELLA GROUP", activeFirm.firm, `GSTIN ${activeFirm.gstin} · RERA ${activeFirm.rera}`, "", `EXPENSE ENTRY ${r.id}`, "", ["Field", "Value"].join(","), ...[["Head", r.cat], ["Department", r.dept], ["Paid to", r.party], ["Amount", r.amt], ["Date", r.date], ["Source", r.src]].map(x => x.join(",")), "", "TRAIL", ...trail.map(t => t.join(","))].join("\n"), "text/csv"); toast(`${r.id} exported`, "green"); }}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Download size={13} /> Export just this</span></GoldButton>
          <GoldButton small ghost onClick={onClose}>Close</GoldButton>
        </div>
        {file && <FilePreview title={`${r.src} — ${r.party}`} meta={r.id} onClose={() => setFile(false)}
          lines={[["Head of expense", r.cat], ["Department", r.dept], ["Amount", inr(r.amt)], ["Date", r.date], ["Source", r.src]]} />}
      </div>
    </Overlay>
  );
}

function ExpensesView({ userKey = "accounts" }) {
  const mob = useIsMobile();
  const { activeFirm, exports, registerExport } = useProc();
  const [exp, setExp] = useState(false);
  const [open, setOpen] = useState(null);
  const [rows, setRows] = useState(EXP_SEED);
  const [intake, setIntake] = useState(false);
  const [q, setQ] = useState("");
  const [by, setBy] = useState("dept");
  const list = rows.filter(r => (r.party + r.cat + r.dept + r.id).toLowerCase().includes(q.toLowerCase()));
  const total = list.reduce((a, r) => a + r.amt, 0);
  const group = {};
  list.forEach(r => { const k = by === "dept" ? r.dept : r.cat; group[k] = (group[k] || 0) + r.amt; });
  const ranked = Object.entries(group).sort((a, b) => b[1] - a[1]);
  const top = ranked[0];
  const filed = (kept) => {
    const add = kept.map((k, i) => ({ id: "EX-" + (9100 + i + Math.floor(Math.random() * 80)), cat: k.cat, dept: k.dept || "Accounts", amt: k.amt, party: k.party, date: k.date, src: "Read by the app", how: "scan", ok: true }));
    setRows(a => [...add, ...a]);
    toast(`${add.length} entries filed into the ledger`, "green");
  };
  return (
    <div>
      <IntakeStyles />
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 14 }}>
        <div><Eyebrow>Accounts · every rupee out</Eyebrow>
          <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 4px" }}>Where the money goes.</h1>
          <div style={{ font: `12px ${sans}`, color: C.stone }}>Every head of expense, and which department is eating it.</div>
        </div>
        <GreenButton onClick={() => setIntake(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Upload size={15} /> Feed a document</span></GreenButton>
      </div>

      <StatementCoverage />
      <Card pad={mob ? 16 : 20} style={{ marginBottom: 16, borderColor: C.goldSoft }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, flexWrap: "wrap" }}>
          <Wallet size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Total spend on record</span>
          <div style={{ marginLeft: "auto", display: "flex", gap: 6 }}>
            {[["dept", "By department"], ["cat", "By head"]].map(([k, l]) => (
              <button key={k} onClick={() => setBy(k)} style={{ cursor: "pointer", border: `1px solid ${by === k ? C.gold : C.line}`, background: by === k ? C.goldTint : "#fff", color: by === k ? C.goldDeep : C.stone, borderRadius: 20, padding: "4px 11px", font: `600 11px ${sans}` }}>{l}</button>
            ))}
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap", marginBottom: 4 }}>
          <span style={{ font: `400 ${mob ? 28 : 36}px ${serif}`, color: C.inkDeep }}>{inr(total)}</span>
          <span style={{ font: `13px ${sans}`, color: C.stone }}>across {list.length} entries</span>
        </div>
        {top && <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginBottom: 12 }}>Biggest appetite: <b style={{ color: C.goldDeep }}>{top[0]}</b> at {inrShort(top[1])} — {Math.round(top[1] / total * 100)}% of everything.</div>}
        {ranked.map(([k, v], i) => (
          <div key={k} style={{ display: "flex", alignItems: "center", gap: 10, padding: "6px 0" }}>
            <span style={{ font: `12px ${sans}`, color: C.inkSoft, width: mob ? 108 : 148, flexShrink: 0 }}>{k}</span>
            <div style={{ flex: 1, height: 8, background: C.lineSoft, borderRadius: 20, overflow: "hidden" }}>
              <div style={{ width: `${total ? (v / total) * 100 : 0}%`, height: "100%", background: i === 0 ? C.gold : C.ink, opacity: i === 0 ? 1 : 0.55, transition: "width .6s" }} />
            </div>
            <span style={{ font: `13px ${mono}`, color: C.ink, minWidth: 78, textAlign: "right" }}>{inrShort(v)}</span>
          </div>
        ))}
      </Card>

      <Card pad={mob ? 14 : 20}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, flexWrap: "wrap" }}>
          <FileText size={15} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>The ledger</span><Pill tone="stone">{list.length}</Pill>
          <div style={{ marginLeft: "auto" }}><ExportButton onClick={() => setExp(true)} /></div>
        </div>
        <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search — canteen, HDFC, subscriptions, EX-9047" style={{ ...inp, margin: "0 0 10px", padding: "9px 11px", fontSize: 13 }} />
        {list.slice(0, 14).map((r, i) => (
          <div key={r.id} onClick={() => setOpen(r)} title="Open this entry" style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}`, flexWrap: "wrap" }}>
            <span style={{ fontSize: 17, width: 24, flexShrink: 0 }}>{HOW_ICON[r.how] || "📄"}</span>
            <div style={{ flex: 1, minWidth: 150 }}>
              <div style={{ font: `600 13px ${sans}`, color: C.ink }}>{r.party}</div>
              <div style={{ font: `11px ${sans}`, color: C.stone }}>{r.cat} · {r.dept} · {r.date} · {r.src}</div>
            </div>
            <span style={{ font: `13px ${mono}`, color: C.ink }}>{inr(r.amt)}</span>
            <span style={{ font: `11px ${mono}`, color: C.stone, minWidth: 62, textAlign: "right" }}>{r.id}</span>
            <ChevronRight size={15} color={C.stone} />
          </div>
        ))}
        {list.length > 14 && <div style={{ font: `12px ${sans}`, color: C.stone, textAlign: "center", paddingTop: 10 }}>+ {list.length - 14} more</div>}
      </Card>

      {open && <ExpenseDetail r={open} onClose={() => setOpen(null)} />}
      {intake && <DocIntake onClose={() => setIntake(false)} onFiled={filed} />}
      {exp && <ExportPanel userKey={userKey} title="Expense ledger" filterNote={q ? `"${q}"` : ""}
        cols={["Ref", "Head of expense", "Department", "Party", "Amount", "Date", "Source"]}
        rows={list.map(r => [r.id, r.cat, r.dept, r.party, r.amt, r.date, r.src])}
        trail={list.slice(0, 8).map(r => [r.id, `Read from ${r.src} and filed under ${r.cat}`, "Accounts", r.date])}
        registry={exports} onRegister={registerExport} onClose={() => setExp(false)} />}
    </div>
  );
}

