const VMONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

const fmtDay = (iso) => new Date(iso + "T00:00:00").toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" });

function vAutoMap(headers) {
  const m = {};
  Object.keys(VEND_ALIASES).forEach(f => { const al = VEND_ALIASES[f].map(normH); let best = -1; headers.forEach((h, i) => { const nh = normH(h); if (best === -1 && al.some(a => nh === a || nh.includes(a) || a.includes(nh))) best = i; }); m[f] = best; });
  return m;
}

function vStatusPill(v) {
  if (v.status === "verified") return <Pill tone="green">✓ Verified · {v.vcode}</Pill>;
  if (v.status === "pending") return <Pill tone="amber">Pending</Pill>;
  return <Pill tone="stone">Unverified</Pill>;
}

