const rowAmt = (r) => numV(r.qty) * numV(r.rate);

function FigureHelper({ onClose }) {
  const mob = useIsMobile();
  const [disp, setDisp] = useState("0");
  const [acc, setAcc] = useState(null);
  const [op, setOp] = useState(null);
  const [fresh, setFresh] = useState(true);
  const [tape, setTape] = useState([]);
  const [flash, setFlash] = useState("");

  const num = parseFloat(disp) || 0;
  const grp = (n) => "₹" + Number(n).toLocaleString("en-IN", { maximumFractionDigits: 2 });
  const words = (n) => wordsIN(n);
  const compute = (a, b, o) => o === "+" ? a + b : o === "-" ? a - b : o === "*" ? a * b : b === 0 ? 0 : a / b;
  const opSym = { "+": "+", "-": "−", "*": "×", "/": "÷" };

  const digit = (d) => { setFlash(""); if (fresh) { setDisp(d); setFresh(false); } else { setDisp(s => (s === "0" ? d : s + d).slice(0, 15)); } };
  const dot = () => { setFlash(""); if (fresh) { setDisp("0."); setFresh(false); } else if (!disp.includes(".")) setDisp(s => s + "."); };
  const clearAll = () => { setDisp("0"); setAcc(null); setOp(null); setFresh(true); setFlash(""); };
  const back = () => { setFlash(""); setDisp(s => (s.length <= 1 || (s.length === 2 && s[0] === "-") ? "0" : s.slice(0, -1))); };
  const operator = (o) => {
    setFlash("");
    if (op != null && !fresh) { const r = compute(acc, num, op); setAcc(r); setDisp(String(r)); }
    else setAcc(num);
    setOp(o); setFresh(true);
  };
  const equals = () => { if (op != null) { const r = compute(acc == null ? 0 : acc, num, op); setDisp(String(r)); setAcc(null); setOp(null); setFresh(true); setFlash(""); } };
  const percent = () => {
    if (op != null && acc != null) { const part = acc * num / 100; setFlash(`${num}% of ${grp(acc)} = ${grp(part)}${op === "-" ? " off" : ""}`); setDisp(String(part)); setFresh(false); }
    else { setDisp(String(num / 100)); setFresh(true); }
  };
  const mul = (f, label) => { const r = num * f; setDisp(String(r)); setFresh(true); setFlash(`× ${label}`); };
  const addTape = () => { if (num) { setTape(t => [...t, num]); } };
  const total = tape.reduce((s, t) => s + t, 0);

  useEffect(() => {
    const h = (e) => {
      const tag = (e.target && e.target.tagName) || "";
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;
      const code = e.code || "";
      // physical numpad — works regardless of NumLock
      if (/^Numpad[0-9]$/.test(code)) { digit(code.slice(6)); e.preventDefault(); return; }
      if (code === "NumpadDecimal") { dot(); e.preventDefault(); return; }
      if (code === "NumpadAdd") { operator("+"); e.preventDefault(); return; }
      if (code === "NumpadSubtract") { operator("-"); e.preventDefault(); return; }
      if (code === "NumpadMultiply") { operator("*"); e.preventDefault(); return; }
      if (code === "NumpadDivide") { operator("/"); e.preventDefault(); return; }
      if (code === "NumpadEnter") { equals(); e.preventDefault(); return; }
      const k = e.key;
      if (k >= "0" && k <= "9") { digit(k); e.preventDefault(); }
      else if (k === ".") { dot(); e.preventDefault(); }
      else if (k === "+") { operator("+"); e.preventDefault(); }
      else if (k === "-") { operator("-"); e.preventDefault(); }
      else if (k === "*" || k === "x" || k === "X") { operator("*"); e.preventDefault(); }
      else if (k === "/") { operator("/"); e.preventDefault(); }
      else if (k === "Enter" || k === "=") { equals(); e.preventDefault(); }
      else if (k === "%") { percent(); e.preventDefault(); }
      else if (k === "Backspace") { back(); e.preventDefault(); }
      else if (k === "Delete" || k === "c" || k === "C") { clearAll(); e.preventDefault(); }
      else if (k === "Escape") { onClose(); }
    };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  });

  const Btn = ({ label, onClick, tone }) => {
    const bg = tone === "op" ? C.goldTint : tone === "eq" ? C.gold : tone === "clear" ? C.redSoft : "#fff";
    const col = tone === "eq" ? "#fff" : tone === "op" ? C.goldDeep : tone === "clear" ? C.red : C.ink;
    return <button onClick={onClick} style={{ cursor: "pointer", border: `1px solid ${tone === "eq" ? C.gold : C.line}`, background: bg, color: col, borderRadius: 10, padding: mob ? "13px 0" : "14px 0", font: `600 ${mob ? 16 : 17}px ${sans}` }}>{label}</button>;
  };

  return (
    <Overlay onClose={onClose} width={440}><div style={{ padding: mob ? 14 : 20 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
        <Calculator size={18} color={C.gold} /><Eyebrow>Figure helper</Eyebrow>
        <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
      </div>
      <h2 style={{ font: `400 20px ${serif}`, margin: "2px 0 10px" }}>Calculator — reads in crore &amp; lakh</h2>

      {/* display */}
      <div style={{ background: C.inkDeep, color: "#fff", borderRadius: 12, padding: "14px 16px", marginBottom: 8, textAlign: "right" }}>
        <div style={{ font: `12px ${mono}`, color: "#9FB2CE", minHeight: 16 }}>{acc != null ? grp(acc) + " " + (op ? opSym[op] : "") : "\u00A0"}</div>
        <div style={{ font: `700 ${mob ? 24 : 28}px ${mono}`, wordBreak: "break-all" }}>{grp(num)}</div>
        <div style={{ font: `12px ${sans}`, color: C.gold, textTransform: "capitalize", minHeight: 16 }}>{words(num)}</div>
        {flash && <div style={{ font: `11px ${sans}`, marginTop: 2, color: "#E9D8AE" }}>{flash}</div>}
      </div>

      {/* big-figure quick keys */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 7, marginBottom: 7 }}>
        <Btn label="× Crore" tone="op" onClick={() => mul(1e7, "1 crore")} />
        <Btn label="× Lakh" tone="op" onClick={() => mul(1e5, "1 lakh")} />
        <Btn label="＋ Tape" tone="op" onClick={addTape} />
      </div>

      {/* keypad */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 7 }}>
        <Btn label="C" tone="clear" onClick={clearAll} />
        <Btn label="⌫" onClick={back} />
        <Btn label="%" tone="op" onClick={percent} />
        <Btn label="÷" tone="op" onClick={() => operator("/")} />
        <Btn label="7" onClick={() => digit("7")} /><Btn label="8" onClick={() => digit("8")} /><Btn label="9" onClick={() => digit("9")} /><Btn label="×" tone="op" onClick={() => operator("*")} />
        <Btn label="4" onClick={() => digit("4")} /><Btn label="5" onClick={() => digit("5")} /><Btn label="6" onClick={() => digit("6")} /><Btn label="−" tone="op" onClick={() => operator("-")} />
        <Btn label="1" onClick={() => digit("1")} /><Btn label="2" onClick={() => digit("2")} /><Btn label="3" onClick={() => digit("3")} /><Btn label="+" tone="op" onClick={() => operator("+")} />
        <Btn label="0" onClick={() => digit("0")} /><Btn label="." onClick={dot} />
        <button onClick={equals} style={{ gridColumn: "span 2", cursor: "pointer", border: `1px solid ${C.gold}`, background: C.gold, color: "#fff", borderRadius: 10, font: `700 ${mob ? 16 : 18}px ${sans}` }}>=</button>
      </div>

      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 8 }}>Your keyboard &amp; numpad work here too. Discount? Type the price, press <b>−</b>, the discount, then <b>%</b> and <b>=</b>. e.g. 2,50,000 − 12 % = ₹2,20,000.</div>

      {tape.length > 0 && (
        <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 10, padding: 12, marginTop: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}><span style={{ font: `600 10px ${sans}`, letterSpacing: "0.1em", textTransform: "uppercase", color: C.stone }}>Tape · {tape.length}</span><button onClick={() => setTape([])} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone, font: `11px ${sans}` }}>Clear</button></div>
          {tape.map((t, i) => <div key={i} style={{ display: "flex", justifyContent: "space-between", font: `12px ${mono}`, color: C.inkSoft, padding: "2px 0" }}><span>{i + 1}.</span><span>{grp(t)}</span></div>)}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", borderTop: `1px solid ${C.line}`, marginTop: 5, paddingTop: 7 }}><span style={{ font: `600 12px ${sans}`, color: C.ink }}>Total</span><div style={{ textAlign: "right" }}><div style={{ font: `700 15px ${mono}`, color: C.goldDeep }}>{grp(total)}</div><div style={{ font: `11px ${sans}`, color: C.stone, textTransform: "capitalize" }}>{words(total)}</div></div></div>
        </div>
      )}
    </div></Overlay>
  );
}

