function buildVCard(p) {
  const parts = p.name.trim().split(" "); const last = parts.length > 1 ? parts[parts.length - 1] : ""; const first = parts.slice(0, parts.length > 1 ? -1 : 1).join(" ");
  return ["BEGIN:VCARD", "VERSION:3.0", `N:${last};${first};;;`, `FN:${p.name}`, "ORG:Marbella Group", `TITLE:${p.designation}`, p.phone && `TEL;TYPE=CELL:${p.phone}`, p.email && `EMAIL;TYPE=WORK:${p.email}`, "URL:https://www.marbellagroup.in", `NOTE:Marbella Group — Employee ID ${p.id}. Verified as of ${fmtToday()}.`, "END:VCARD"].filter(Boolean).join("\n");
}

