const DEFAULT_SHIFT = { in: "09:30", out: "18:30", hours: 9 };

const rec = (date, i, o) => ({ date, in: i, out: o });

const ab = (date) => ({ date, in: null, out: null });

const toMin = (t) => { if (!t) return null; const [h, m] = t.split(":").map(Number); return h * 60 + (m || 0); };

function taskStats(name, hrTasks) {
  const mine = hrTasks.filter(t => t.who === name);
  return { done: mine.filter(t => t.done).length, total: mine.length };
}

const normH = (s) => (s || "").toString().toLowerCase().replace(/[\s_\-.:/()]/g, "").trim();

function autoMap(headers) {
  const m = { id: -1, name: -1, date: -1, in: -1, out: -1 };
  Object.keys(ATT_ALIASES).forEach(field => {
    const aliases = ATT_ALIASES[field].map(normH);
    let best = -1;
    headers.forEach((h, i) => { const nh = normH(h); if (best === -1 && aliases.some(a => nh === a || nh.includes(a) || a.includes(nh))) best = i; });
    m[field] = best;
  });
  return m;
}

function parseCSV(text) {
  const lines = text.trim().split(/\r?\n/).filter(l => l.trim());
  const split = (line) => { const out = []; let cur = "", q = false; for (const ch of line) { if (ch === '"') q = !q; else if (ch === "," && !q) { out.push(cur.trim()); cur = ""; } else cur += ch; } out.push(cur.trim()); return out; };
  const headers = lines.length ? split(lines[0]) : [];
  const rows = lines.slice(1).map(split);
  return { headers, rows };
}

function normalizeRows(rows, headers, map, people) {
  const at = (row, i) => (i >= 0 && i < row.length ? row[i] : "");
  const byId = Object.fromEntries(people.map(p => [p.id, p]));
  return rows.map(r => {
    let id = at(r, map.id).trim();
    const nm = at(r, map.name).trim();
    if (!byId[id] && nm) { const hit = people.find(p => p.name.toLowerCase() === nm.toLowerCase()); if (hit) id = hit.id; }
    return { id, name: nm, date: at(r, map.date).trim(), in: at(r, map.in).trim(), out: at(r, map.out).trim() };
  }).filter(r => r.id || r.name);
}

