function parseSheet(text) {
  const lines = String(text).replace(/\r/g, "").split("\n").filter(l => l.trim());
  if (!lines.length) return { head: [], rows: [] };
  const split = (l) => {
    const out = []; let cur = "", q = false;
    for (const ch of l) {
      if (ch === '"') q = !q;
      else if (ch === "," && !q) { out.push(cur); cur = ""; }
      else cur += ch;
    }
    out.push(cur); return out.map(x => x.trim());
  };
  const head = split(lines[0]);
  const rows = lines.slice(1).map(split);
  return { head, rows };
}

const guessMap = (head) => {
  const m = {};
  head.forEach((h, i) => {
    const s = h.toLowerCase().replace(/[^a-z ]/g, "").trim();
    const f = IMP_FIELDS.find(f => f.aliases.some(a => s === a || s.includes(a)));
    if (f && m[f.k] === undefined) m[f.k] = i;
  });
  return m;
};

const normDate = (s) => {
  const t = String(s).trim();
  const M = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  let m = t.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) { const d = +m[1], mo = +m[2], y = m[3].length === 2 ? 2000 + +m[3] : +m[3]; if (mo >= 1 && mo <= 12) return `${String(d).padStart(2,"0")} ${M[mo-1]} ${y}`; }
  m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return `${m[3]} ${M[+m[2]-1]} ${m[1]}`;
  return t;
};

function BulkImportView() {
  const mob = useIsMobile();
  const { people, bulkAddPeople, offices } = useProc();
  const [raw, setRaw] = useState("");
  const [step, setStep] = useState(1);
  const [head, setHead] = useState([]);
  const [rows, setRows] = useState([]);
  const [map, setMap] = useState({});
  const [done, setDone] = useState(null);

  const read = (text) => {
    const { head, rows } = parseSheet(text);
    if (!head.length) { toast("Nothing to read in that", "amber"); return; }
    setHead(head); setRows(rows); setMap(guessMap(head)); setStep(2);
  };
  const val = (r, k) => (map[k] === undefined ? "" : (r[map[k]] || "").trim());

  const checked = useMemo(() => rows.map((r, i) => {
    const rec = {}; IMP_FIELDS.forEach(f => { rec[f.k] = val(r, f.k); });
    const errs = [], warns = [];
    IMP_FIELDS.filter(f => f.req).forEach(f => { if (!rec[f.k]) errs.push(`${f.label} is blank`); });
    if (rec.phone && !phoneOK(rec.phone)) errs.push("Mobile isn't a valid 10-digit Indian number");
    if (rec.email && !emailOK(rec.email)) errs.push("Email isn't a valid address");
    if (rec.email && isCompanyEmail(rec.email)) errs.push("That's a company address — this field is for their personal email");
    if (rec.imei && !luhnOK(rec.imei)) errs.push("IMEI fails its check digit");
    if (!rec.email) warns.push("No personal email — they can't be reached after exit");
    if (rec.id && people.some(p => p.id === rec.id)) errs.push(`${rec.id} already exists on the roster`);
    const dupe = rows.findIndex((o, j) => j < i && (o[map.phone] || "").trim() && (o[map.phone] || "").trim() === rec.phone);
    if (dupe >= 0) errs.push(`Same mobile as row ${dupe + 2}`);
    return { i, rec, errs, warns };
  }), [rows, map, people]);

  const good = checked.filter(c => !c.errs.length);
  const bad = checked.filter(c => c.errs.length);

  /* EDIT 4 of 5: `await`.

     bulkAddPeople now goes to the server, which is what assigns the employee
     IDs, resolves the employer from the posting and normalises the dates. The
     count shown is therefore what actually LANDED, not what was attempted —
     rows the server held back are not counted as added. */
  const commit = async () => {
    const made = await bulkAddPeople(good.map(c => c.rec));
    setDone({ n: made.length, skipped: bad.length + (good.length - made.length) });
    setStep(4);
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Bulk intake</Eyebrow><Pill tone="gold">HR only</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Bring an existing list in.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 660, margin: "0 0 18px", lineHeight: 1.55 }}>
        Paste a sheet or drop a CSV. The columns get matched for you — you check the matching, then the rows are
        validated one by one. Anything that fails is held back with a reason, not quietly dropped.
      </p>

      <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
        {["Paste the sheet", "Match the columns", "Check the rows", "Done"].map((s, i) => {
          const n = i + 1, on = step === n, past = step > n;
          return (
            <div key={s} style={{ display: "flex", alignItems: "center", gap: 7, padding: "7px 13px", borderRadius: 20,
              background: on ? C.ink : past ? C.greenSoft : C.panel, color: on ? "#fff" : past ? C.green : C.stone,
              border: `1px solid ${on ? C.ink : past ? C.green : C.line}`, font: `600 12px ${sans}` }}>
              <span style={{ width: 18, height: 18, borderRadius: "50%", background: on ? "rgba(255,255,255,.2)" : past ? C.green : C.lineSoft,
                color: on ? "#fff" : past ? "#fff" : C.stone, display: "grid", placeItems: "center", font: `700 10px ${sans}` }}>
                {past ? "\u2713" : n}
              </span>{s}
            </div>
          );
        })}
      </div>

      {step === 1 && (
        <Card pad={mob ? 16 : 20}>
          <label style={lbl}>Paste your sheet here — headers on the first line</label>
          <textarea value={raw} onChange={e => setRaw(e.target.value)} rows={10}
            placeholder="Employee Name,Designation,Department,DOJ,Personal Mobile…"
            style={{ ...inp, fontFamily: mono, fontSize: 12, resize: "vertical", margin: "8px 0 12px" }} />
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <GoldButton onClick={() => read(raw)}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Upload size={15} /> Read this sheet</span>
            </GoldButton>
            <GoldButton ghost small onClick={() => { setRaw(SAMPLE_CSV); toast("Sample loaded — press Read", "gold"); }}>Use a sample</GoldButton>
          </div>
          <div style={{ display: "flex", alignItems: "flex-start", gap: 7, marginTop: 14, font: `12px ${sans}`, color: C.stone, lineHeight: 1.55 }}>
            <Info size={14} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} />
            Column names don't have to match ours — "DOJ", "Joining Date" and "Date of Joining" all land in the same place.
            Excel: save as CSV first, or copy the cells and paste straight in.
          </div>
        </Card>
      )}

      {step === 2 && (
        <Card pad={mob ? 16 : 20}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
            <Wand2 size={16} color={C.gold} /><Eyebrow>Matched {Object.keys(map).length} of {head.length} columns</Eyebrow>
            <span style={{ marginLeft: "auto", font: `12px ${sans}`, color: C.stone }}>{rows.length} rows</span>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1fr 1fr", gap: 10 }}>
            {IMP_FIELDS.map(f => (
              <div key={f.k} style={{ display: "flex", alignItems: "center", gap: 9, background: C.paper, borderRadius: 9, padding: "9px 11px" }}>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", font: `600 12px ${sans}`, color: C.ink }}>{f.label}{f.req && <span style={{ color: C.red }}> *</span>}</span>
                </span>
                <select value={map[f.k] === undefined ? "" : map[f.k]}
                  onChange={e => setMap(m => ({ ...m, [f.k]: e.target.value === "" ? undefined : Number(e.target.value) }))}
                  style={{ font: `12px ${sans}`, padding: "6px 8px", border: `1px solid ${map[f.k] === undefined && f.req ? C.red : C.line}`, borderRadius: 7, background: "#fff", color: C.ink, maxWidth: 170 }}>
                  <option value="">— not in sheet —</option>
                  {head.map((h, i) => <option key={i} value={i}>{h}</option>)}
                </select>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 16, flexWrap: "wrap" }}>
            <button onClick={() => setStep(1)} style={softBtn}>Back</button>
            <GoldButton onClick={() => {
              const miss = IMP_FIELDS.filter(f => f.req && map[f.k] === undefined);
              if (miss.length) { toast(`Still need: ${miss.map(m => m.label).join(", ")}`, "amber"); return; }
              setStep(3);
            }}>Check the rows</GoldButton>
          </div>
        </Card>
      )}

      {step === 3 && (
        <>
          <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(3,1fr)", gap: 12, marginBottom: 16 }}>
            {[["Ready to import", good.length, C.green], ["Held back", bad.length, bad.length ? C.red : C.stone],
              ["Missing personal email", checked.filter(c => c.warns.length).length, C.amber]].map(([k, v, col]) => (
              <Card key={k} pad={14}>
                <div style={{ font: `700 26px ${mono}`, color: col }}>{v}</div>
                <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 3 }}>{k}</div>
              </Card>
            ))}
          </div>

          {bad.length > 0 && (
            <Card pad={mob ? 14 : 18} style={{ marginBottom: 14, borderColor: C.red }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                <TriangleAlert size={15} color={C.red} /><Eyebrow color={C.red}>Held back — fix these in your sheet and paste again</Eyebrow>
              </div>
              {bad.slice(0, 12).map(c => (
                <div key={c.i} style={{ padding: "9px 0", borderTop: `1px solid ${C.lineSoft}` }}>
                  <div style={{ font: `600 13px ${sans}`, color: C.ink }}>Row {c.i + 2} · {c.rec.name || "(no name)"}</div>
                  {c.errs.map((e, k) => <div key={k} style={{ font: `12px ${sans}`, color: C.red, marginTop: 3 }}>· {e}</div>)}
                </div>
              ))}
              {bad.length > 12 && <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 8 }}>…and {bad.length - 12} more.</div>}
            </Card>
          )}

          <Card pad={mob ? 14 : 18}>
            <Eyebrow>What will be created</Eyebrow>
            <div style={{ overflowX: "auto", marginTop: 10 }}>
              <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 640 }}>
                <thead><tr>{["Name", "Designation", "Dept", "Joined", "Mobile", "Gross"].map(h =>
                  <th key={h} style={{ textAlign: "left", font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, padding: "0 10px 8px 0", borderBottom: `1px solid ${C.line}` }}>{h}</th>)}</tr></thead>
                <tbody>
                  {good.slice(0, 10).map(c => (
                    <tr key={c.i}>
                      <td style={{ padding: "9px 10px 9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `600 13px ${sans}`, color: C.ink }}>{c.rec.name}</td>
                      <td style={{ padding: "9px 10px 9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.inkSoft }}>{c.rec.desig}</td>
                      <td style={{ padding: "9px 10px 9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.inkSoft }}>{c.rec.dept}</td>
                      <td style={{ padding: "9px 10px 9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.stone }}>{normDate(c.rec.joined)}</td>
                      <td style={{ padding: "9px 10px 9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${mono}`, color: C.inkSoft }}>{c.rec.phone}</td>
                      <td style={{ padding: "9px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${mono}`, color: C.ink }}>
                        {rupee((+c.rec.basic || 0) + (+c.rec.hra || 0) + (+c.rec.special || 0))}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {good.length > 10 && <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 8 }}>…and {good.length - 10} more.</div>}
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 16, flexWrap: "wrap" }}>
              <button onClick={() => setStep(2)} style={softBtn}>Back to matching</button>
              <GoldButton onClick={() => good.length ? commit() : toast("Nothing passes yet", "amber")}>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 7, opacity: good.length ? 1 : .5 }}>
                  <UserPlus size={15} /> Import {good.length} {good.length === 1 ? "person" : "people"}
                </span>
              </GoldButton>
            </div>
          </Card>
        </>
      )}

      {step === 4 && done && (
        <Card pad={mob ? 18 : 24}>
          <div style={{ textAlign: "center", padding: "10px 0 4px" }}>
            <div style={{ width: 54, height: 54, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px", color: C.green }}><CheckCircle2 size={26} /></div>
            <div style={{ font: `400 22px ${serif}`, color: C.ink }}>{done.n} {done.n === 1 ? "person" : "people"} on the roster.</div>
            <div style={{ font: `13px ${sans}`, color: C.inkSoft, marginTop: 8, lineHeight: 1.55, maxWidth: 460, margin: "8px auto 0" }}>
              Each one has an Employee ID, sits in the org tree under their department head, and is in the ledger.
              {done.skipped > 0 && <> {done.skipped} {done.skipped === 1 ? "row was" : "rows were"} held back.</>}
            </div>
            <div style={{ font: `12px ${sans}`, color: C.amber, marginTop: 12 }}>
              None of them has a photo or a verified number yet — that's the next job.
            </div>
          </div>
          <div style={{ display: "flex", gap: 8, justifyContent: "center", marginTop: 18, flexWrap: "wrap" }}>
            <GoldButton small onClick={() => { setStep(1); setRaw(""); setDone(null); }}>Import another sheet</GoldButton>
          </div>
        </Card>
      )}
    </div>
  );
}

function PhotoCapture({ p, onClose, onSave }) {
  const mob = useIsMobile();
  const vid = React.useRef(null), can = React.useRef(null);
  const [state, setState] = useState("asking");
  const [shot, setShot] = useState(null);
  const [err, setErr] = useState("");
  useEffect(() => {
    let stream;
    (async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user", width: 480, height: 480 } });
        if (vid.current) { vid.current.srcObject = stream; await vid.current.play(); setState("live"); }
      } catch (e) { setErr(e && e.message ? e.message : "Camera unavailable"); setState("blocked"); }
    })();
    return () => { if (stream) stream.getTracks().forEach(t => t.stop()); };
  }, []);
  const snap = () => {
    const v = vid.current, c = can.current;
    if (!v || !c) return;
    const s = Math.min(v.videoWidth, v.videoHeight);
    c.width = 320; c.height = 320;
    c.getContext("2d").drawImage(v, (v.videoWidth - s) / 2, (v.videoHeight - s) / 2, s, s, 0, 0, 320, 320);
    setShot(c.toDataURL("image/jpeg", 0.82)); setState("shot");
  };
  return (
    <Overlay onClose={onClose} width={430}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <Camera size={18} color={C.gold} /><Eyebrow>Live photo — {p.name}</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <div style={{ width: "100%", aspectRatio: "1", borderRadius: 14, overflow: "hidden", background: C.inkDeep, display: "grid", placeItems: "center", marginBottom: 14 }}>
          {state === "shot" ? <img src={shot} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            : <video ref={vid} playsInline muted style={{ width: "100%", height: "100%", objectFit: "cover", display: state === "live" ? "block" : "none" }} />}
          {state === "asking" && <div style={{ color: "#9AA6BC", font: `13px ${sans}` }}>Asking for the camera…</div>}
          {state === "blocked" && (
            <div style={{ textAlign: "center", padding: 22 }}>
              <Camera size={26} color="#7E8AA0" />
              <div style={{ font: `600 13px ${sans}`, color: "#E8ECF4", marginTop: 10 }}>No camera here</div>
              <div style={{ font: `11px ${sans}`, color: "#9AA6BC", marginTop: 6, lineHeight: 1.5 }}>{err}</div>
              <div style={{ font: `11px ${sans}`, color: "#7E8AA0", marginTop: 8, lineHeight: 1.5 }}>
                Browsers only hand over the camera on a secure page with permission granted. On the live site it will open.
              </div>
            </div>
          )}
        </div>
        <canvas ref={can} style={{ display: "none" }} />
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {state === "live" && <GoldButton onClick={snap}><span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Camera size={15} /> Take the photo</span></GoldButton>}
          {state === "shot" && <>
            <GreenButton onClick={() => { onSave(shot); onClose(); }}><Check size={14} /> Use this</GreenButton>
            <button onClick={() => setState("live")} style={softBtn}>Retake</button>
          </>}
        </div>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 12, lineHeight: 1.55 }}>
          Taken here and now, not uploaded from a gallery — that's the point of a live photo. It goes on the ID card and the gate screen.
        </div>
      </div>
    </Overlay>
  );
}

function OtpVerify({ p, channel, target, onClose, onVerified }) {
  const mob = useIsMobile();
  const [code] = useState(() => String(Math.floor(100000 + Math.random() * 900000)));
  const [typed, setTyped] = useState("");
  const [left, setLeft] = useState(120);
  const [err, setErr] = useState("");
  useEffect(() => { const t = setInterval(() => setLeft(l => Math.max(0, l - 1)), 1000); return () => clearInterval(t); }, []);
  const mm = String(Math.floor(left / 60)).padStart(2, "0"), ss = String(left % 60).padStart(2, "0");
  return (
    <Overlay onClose={onClose} width={420}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          {channel === "phone" ? <Phone size={18} color={C.gold} /> : <Mail size={18} color={C.gold} />}
          <Eyebrow>Verify {channel === "phone" ? "mobile" : "email"}</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <div style={{ font: `13px ${sans}`, color: C.inkSoft, margin: "8px 0 14px", lineHeight: 1.55 }}>
          A six-digit code for <b style={{ color: C.ink }}>{p.name}</b> at <b style={{ color: C.ink }}>{target}</b>.
        </div>
        <div style={{ background: C.goldTint, border: `1px solid ${C.gold}`, borderRadius: 11, padding: 14, marginBottom: 14 }}>
          <div style={{ font: `600 10px ${sans}`, letterSpacing: ".12em", textTransform: "uppercase", color: C.goldDeep, marginBottom: 6 }}>Demo — the code is shown here</div>
          <div style={{ font: `700 30px ${mono}`, letterSpacing: ".18em", color: C.ink, textAlign: "center" }}>{code}</div>
          <div style={{ font: `11px ${sans}`, color: C.inkSoft, marginTop: 8, lineHeight: 1.55 }}>
            On the live system this is sent by SMS or email and never appears on screen. Sending needs a gateway —
            a backend job. What's real here is the flow, the expiry and the record.
          </div>
        </div>
        <label style={lbl}>Enter the code they read back</label>
        <input value={typed} onChange={e => { setTyped(e.target.value.replace(/\D/g, "").slice(0, 6)); setErr(""); }}
          placeholder="000000" style={{ ...inp, font: `700 20px ${mono}`, letterSpacing: ".2em", textAlign: "center", margin: "8px 0 6px", borderColor: err ? C.red : C.line }} />
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
          <Clock size={13} color={left ? C.stone : C.red} />
          <span style={{ font: `12px ${sans}`, color: left ? C.stone : C.red }}>{left ? `Expires in ${mm}:${ss}` : "Expired — start again"}</span>
        </div>
        {err && <div style={{ font: `12px ${sans}`, color: C.red, marginBottom: 10, display: "flex", alignItems: "center", gap: 5 }}><TriangleAlert size={13} /> {err}</div>}
        <GoldButton onClick={() => {
          if (!left) { setErr("That code has expired."); return; }
          if (typed !== code) { setErr("Doesn't match. Read it back once more."); return; }
          onVerified(); onClose();
        }}>Confirm</GoldButton>
      </div>
    </Overlay>
  );
}

const EXIT_STAGES = [
  { k: "decision", label: "Decision recorded",     icon: PenLine,      blurb: "Why, when, and who signed it off." },
  { k: "handover", label: "Work handed over",      icon: ClipboardList,blurb: "Files, keys, pending jobs — to a named person." },
  { k: "assets",   label: "Assets & access back",  icon: LockIcon,     blurb: "Devices returned, card killed, logins revoked." },
  { k: "dues",     label: "Full & final settled",  icon: Wallet,       blurb: "Salary, leave encashment, recoveries." },
  { k: "papers",   label: "Papers issued",         icon: FileText,     blurb: "Relieving letter and character certificate." },
  { k: "closed",   label: "Employment ended",      icon: CheckCircle2, blurb: "Signed, paid, closed." },
];

const EXIT_REASONS = ["Resigned", "Terminated — performance", "Terminated — conduct", "Contract ended", "Retirement", "Absconded"];

function Flowchart({ stages, current, doneKeys, onPick, blocked }) {
  const mob = useIsMobile();
  return (
    <div style={{ display: mob ? "block" : "flex", alignItems: "stretch", gap: 0, overflowX: "auto", paddingBottom: 4 }}>
      {stages.map((s, i) => {
        const done = doneKeys.includes(s.k);
        const cur = current === s.k;
        const lock = !done && !cur;
        const Ic = s.icon;
        const col = done ? C.green : cur ? C.gold : C.line;
        return (
          <React.Fragment key={s.k}>
            <button onClick={() => (done || cur) && onPick(s.k)}
              style={{ cursor: done || cur ? "pointer" : "default", flex: mob ? "none" : 1, minWidth: mob ? "auto" : 140,
                width: mob ? "100%" : "auto", textAlign: "left", background: cur ? "#fff" : done ? C.greenSoft : C.panel,
                border: `1.5px solid ${col}`, borderRadius: 12, padding: "12px 13px", opacity: lock ? .55 : 1,
                marginBottom: mob ? 8 : 0, boxShadow: cur ? `0 6px 18px ${C.gold}33` : "none" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                <span style={{ width: 26, height: 26, borderRadius: 8, background: done ? C.green : cur ? C.gold : C.lineSoft,
                  color: done || cur ? "#fff" : C.stone, display: "grid", placeItems: "center", flexShrink: 0 }}>
                  {done ? <Check size={14} /> : lock ? <LockIcon size={13} /> : <Ic size={14} />}
                </span>
                <span style={{ font: `700 10px ${mono}`, color: C.stone }}>{i + 1}</span>
                {cur && <Pill tone="gold">now</Pill>}
              </div>
              <div style={{ font: `600 12px ${sans}`, color: C.ink, lineHeight: 1.3 }}>{s.label}</div>
              <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 4, lineHeight: 1.45 }}>{s.blurb}</div>
            </button>
            {i < stages.length - 1 && (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: mob ? "0 0 8px" : "0 6px", flexShrink: 0 }}>
                {mob ? <span style={{ display: "block", width: 2, height: 14, background: doneKeys.includes(s.k) ? C.green : C.line, marginLeft: 26 }} />
                     : <ArrowRight size={15} color={doneKeys.includes(s.k) ? C.green : C.line} />}
              </div>
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}

function ExitRunner({ ex, p, onClose }) {
  const mob = useIsMobile();
  const { advanceExit, devices, cardLog, salaries, people } = useProc();
  const [view, setView] = useState(ex.stage);
  const [f, setF] = useState({});
  const set = (k, v) => setF(s => ({ ...s, [k]: v }));
  const myDevices = devices.filter(d => d.pid === p.id);
  const sal = salaries[p.id];
  const doneKeys = EXIT_STAGES.map(s => s.k).slice(0, EXIT_STAGES.findIndex(s => s.k === ex.stage));
  const stageIdx = EXIT_STAGES.findIndex(s => s.k === ex.stage);
  const viewing = EXIT_STAGES.find(s => s.k === view);
  const isCurrent = view === ex.stage;

  const submit = (payload, summary) => {
    advanceExit(ex.id, payload, summary);
    setF({});
    const nx = EXIT_STAGES[Math.min(EXIT_STAGES.length - 1, stageIdx + 1)];
    setView(nx.k);
    toast(summary, "green");
  };

  const daily = sal ? Math.round(net(sal) / 30) : 0;
  const leaveDays = Number(f.leaveBal || 0);
  const worked = Number(f.workedDays || 0);
  const recover = Number(f.recover || 0);
  const settle = (worked * daily) + (leaveDays * daily) + Number(f.gratuity || 0) - recover;

  return (
    <Overlay onClose={onClose} width={760}>
      <div style={{ padding: mob ? 16 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <LogOut size={18} color={C.red} /><Eyebrow color={C.red}>Deboarding</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h3 style={{ font: `400 21px ${serif}`, margin: "6px 0 3px", color: C.ink }}>{p.name}</h3>
        <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginBottom: 16 }}>{p.designation} · {p.dept} · <span style={{ font: `600 12px ${mono}`, color: C.goldDeep }}>{p.id}</span></div>

        <Flowchart stages={EXIT_STAGES} current={ex.stage} doneKeys={doneKeys} onPick={setView} />

        <div style={{ marginTop: 18, borderTop: `1px solid ${C.line}`, paddingTop: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
            <Eyebrow>{viewing.label}</Eyebrow>
            {!isCurrent && <Pill tone="green">already done</Pill>}
          </div>

          {!isCurrent && (
            <div style={{ background: C.greenSoft, borderRadius: 10, padding: 14, font: `12px ${sans}`, color: C.ink, lineHeight: 1.65 }}>
              {(ex.record[view] ? Object.entries(ex.record[view]) : []).map(([k, v]) => (
                <div key={k} style={{ display: "flex", gap: 10, padding: "3px 0" }}>
                  <span style={{ width: 140, color: C.stone, flexShrink: 0, textTransform: "capitalize" }}>{k.replace(/([A-Z])/g, " $1")}</span>
                  <span style={{ fontWeight: 600 }}>{String(v)}</span>
                </div>
              ))}
              {!ex.record[view] && <span style={{ color: C.stone }}>Nothing recorded at this step.</span>}
            </div>
          )}

          {isCurrent && view === "decision" && (
            <>
              <label style={lbl}>Why are they leaving</label>
              <select value={f.reason || ""} onChange={e => set("reason", e.target.value)} style={{ ...inp, margin: "7px 0 14px" }}>
                <option value="">— choose —</option>{EXIT_REASONS.map(r => <option key={r}>{r}</option>)}
              </select>
              <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1fr 1fr", gap: 12 }}>
                <div><label style={lbl}>Last working day</label><input type="date" value={f.lwd || ""} onChange={e => set("lwd", e.target.value)} style={{ ...inp, margin: "7px 0 14px" }} /></div>
                <div><label style={lbl}>Approved by</label><input value={f.approver || ""} onChange={e => set("approver", e.target.value)} placeholder="Name and designation" style={{ ...inp, margin: "7px 0 14px" }} /></div>
              </div>
              <Field label="What happened" area hint="Plain sentences. This is what gets read back in a dispute — not a code."
                value={f.note || ""} onChange={v => set("note", v)} placeholder="Resigned on 12 Aug citing a family move to Delhi. Served notice in full." />
              <GoldButton onClick={() => {
                if (!f.reason || !f.lwd || !f.approver || (f.note || "").trim().length < 20) { toast("Reason, last day, approver and a real note", "amber"); return; }
                submit({ reason: f.reason, lastWorkingDay: f.lwd, approvedBy: f.approver, note: f.note }, `Exit opened — ${p.name} (${f.reason})`);
              }}>Record the decision</GoldButton>
            </>
          )}

          {isCurrent && view === "handover" && (
            <>
              <Field label="Handing over to" hint="One named person. Not 'the team'." value={f.to || ""} onChange={v => set("to", v)} placeholder="e.g. A. Sethi (MB-PUR-0018)" />
              <Field label="What's being handed over" area hint="Files, keys, running jobs, passwords for shared tools, anything half-finished."
                value={f.what || ""} onChange={v => set("what", v)} placeholder="Open POs 4471 and 4468, vendor files A–M, store keys, the RMC rate file." />
              <button onClick={() => set("signed", !f.signed)} style={{ width: "100%", textAlign: "left", cursor: "pointer",
                border: `1px solid ${f.signed ? C.green : C.line}`, background: f.signed ? C.greenSoft : "#fff", borderRadius: 11, padding: "13px 15px", display: "flex", gap: 11, alignItems: "center", marginBottom: 14 }}>
                <span style={{ width: 22, height: 22, borderRadius: 6, border: `1.5px solid ${f.signed ? C.green : C.line}`, background: f.signed ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}>{f.signed && <Check size={14} color="#fff" />}</span>
                <span style={{ font: `600 13px ${sans}`, color: C.ink }}>Receiver has signed the handover note</span>
              </button>
              <GoldButton onClick={() => {
                if (!f.to || (f.what || "").trim().length < 15 || !f.signed) { toast("Name the receiver, list the work, get it signed", "amber"); return; }
                submit({ handedTo: f.to, items: f.what, signed: "Yes" }, `Handover signed — ${p.name} to ${f.to}`);
              }}>Record the handover</GoldButton>
            </>
          )}

          {isCurrent && view === "assets" && (
            <>
              <div style={{ background: C.paper, borderRadius: 11, padding: 14, marginBottom: 14 }}>
                <div style={{ font: `600 11px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, marginBottom: 9 }}>Issued to this person</div>
                {myDevices.length ? myDevices.map(d => (
                  <div key={d.id} style={{ display: "flex", alignItems: "center", gap: 9, padding: "6px 0", font: `12px ${sans}` }}>
                    <Pill tone="stone">{d.type}</Pill>
                    <span style={{ color: C.ink, fontWeight: 600 }}>{d.model}</span>
                    <span style={{ marginLeft: "auto", font: `11px ${mono}`, color: C.stone }}>{d.imei !== "\u2014" ? "IMEI " + d.imei : d.sim}</span>
                  </div>
                )) : <div style={{ font: `12px ${sans}`, color: C.stone }}>No devices on record.</div>}
                <div style={{ marginTop: 8, paddingTop: 8, borderTop: `1px solid ${C.line}`, font: `12px ${sans}`, color: C.inkSoft }}>
                  Card <b style={{ color: C.ink }}>v{Math.max(0, ...cardLog.filter(c => c.pid === p.id).map(c => c.ver))}</b> is still live and opens {zonesFor(p).length} area{zonesFor(p).length > 1 ? "s" : ""}.
                </div>
              </div>
              {[["devices", `All ${myDevices.length} device${myDevices.length === 1 ? "" : "s"} returned and wiped`],
                ["card", "ID card taken back, cut, and cancelled at every gate"],
                ["logins", "Email, app logins and shared passwords revoked"],
                ["sim", "Company SIM deactivated or ported out"],
                ["keys", "Keys, locker and vehicle passes returned"]].map(([k, t]) => (
                <button key={k} onClick={() => set(k, !f[k])} style={{ width: "100%", textAlign: "left", cursor: "pointer",
                  border: `1px solid ${f[k] ? C.green : C.line}`, background: f[k] ? C.greenSoft : "#fff", borderRadius: 10, padding: "11px 13px", display: "flex", gap: 10, alignItems: "center", marginBottom: 7 }}>
                  <span style={{ width: 20, height: 20, borderRadius: 5, border: `1.5px solid ${f[k] ? C.green : C.line}`, background: f[k] ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}>{f[k] && <Check size={13} color="#fff" />}</span>
                  <span style={{ font: `12px ${sans}`, color: C.ink }}>{t}</span>
                </button>
              ))}
              <div style={{ marginTop: 12 }}>
                <GoldButton onClick={() => {
                  const need = ["devices", "card", "logins", "sim", "keys"].filter(k => !f[k]);
                  if (need.length) { toast(`${need.length} still outstanding`, "amber"); return; }
                  submit({ devicesReturned: myDevices.length, cardCancelled: "Yes", loginsRevoked: "Yes", simClosed: "Yes", keysReturned: "Yes" },
                    `Access revoked — ${p.name}`);
                }}>Everything is back — revoke access</GoldButton>
              </div>
            </>
          )}

          {isCurrent && view === "dues" && (
            <>
              {!sal && <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: "11px 13px", marginBottom: 14, font: `12px ${sans}`, color: "#6E4E12" }}>
                No salary structure on record for this person — enter the figures manually and fix the record afterwards.
              </div>}
              <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(4,1fr)", gap: 10, marginBottom: 14 }}>
                <div><label style={lbl}>Days worked</label><input type="number" value={f.workedDays || ""} onChange={e => set("workedDays", e.target.value)} style={{ ...inp, margin: "6px 0 0" }} /></div>
                <div><label style={lbl}>Leave balance</label><input type="number" value={f.leaveBal || ""} onChange={e => set("leaveBal", e.target.value)} style={{ ...inp, margin: "6px 0 0" }} /></div>
                <div><label style={lbl}>Gratuity</label><input type="number" value={f.gratuity || ""} onChange={e => set("gratuity", e.target.value)} style={{ ...inp, margin: "6px 0 0" }} /></div>
                <div><label style={lbl}>Recoveries</label><input type="number" value={f.recover || ""} onChange={e => set("recover", e.target.value)} style={{ ...inp, margin: "6px 0 0" }} /></div>
              </div>
              <div style={{ background: C.paper, borderRadius: 11, padding: 14, marginBottom: 14 }}>
                {[["Net monthly", sal ? rupee(net(sal)) : "—"], ["A day", daily ? rupee(daily) : "—"],
                  ["Days worked", `${worked} × ${daily ? rupee(daily) : "—"}`],
                  ["Leave encashed", `${leaveDays} × ${daily ? rupee(daily) : "—"}`],
                  ["Gratuity", rupee(Number(f.gratuity || 0))], ["Less recoveries", "\u2212 " + rupee(recover)]].map(([k, v]) => (
                  <div key={k} style={{ display: "flex", padding: "4px 0", font: `12px ${sans}` }}>
                    <span style={{ flex: 1, color: C.stone }}>{k}</span><span style={{ color: C.ink, fontWeight: 600 }}>{v}</span>
                  </div>
                ))}
                <div style={{ display: "flex", marginTop: 9, paddingTop: 9, borderTop: `1px solid ${C.line}` }}>
                  <span style={{ flex: 1, font: `600 13px ${sans}`, color: C.ink }}>Full &amp; final</span>
                  <span style={{ font: `700 18px ${mono}`, color: settle >= 0 ? C.green : C.red }}>{rupee(settle)}</span>
                </div>
              </div>
              <Field label="Anything to note" area hint="Deductions explained, disputes, agreed instalments." value={f.dueNote || ""} onChange={v => set("dueNote", v)} placeholder="Notice period shortfall of 6 days waived by Chairman." />
              <GoldButton onClick={() => {
                if (!worked) { toast("Enter days worked", "amber"); return; }
                submit({ daysWorked: worked, leaveEncashed: leaveDays, gratuity: rupee(Number(f.gratuity || 0)), recoveries: rupee(recover), settlement: rupee(settle), note: f.dueNote || "—" },
                  `F&F computed — ${p.name} · ${rupee(settle)}`);
              }}>Freeze the settlement</GoldButton>
            </>
          )}

          {isCurrent && view === "papers" && (
            <>
              <div style={{ font: `13px ${sans}`, color: C.inkSoft, marginBottom: 14, lineHeight: 1.55 }}>
                Two documents. The relieving letter says employment has ended. The character certificate says how they conducted themselves — write it honestly, because it follows them.
              </div>
              {[["reliev", "Relieving letter prepared and signed"], ["char", "Character certificate prepared and signed"]].map(([k, t]) => (
                <button key={k} onClick={() => set(k, !f[k])} style={{ width: "100%", textAlign: "left", cursor: "pointer",
                  border: `1px solid ${f[k] ? C.green : C.line}`, background: f[k] ? C.greenSoft : "#fff", borderRadius: 10, padding: "11px 13px", display: "flex", gap: 10, alignItems: "center", marginBottom: 8 }}>
                  <span style={{ width: 20, height: 20, borderRadius: 5, border: `1.5px solid ${f[k] ? C.green : C.line}`, background: f[k] ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}>{f[k] && <Check size={13} color="#fff" />}</span>
                  <span style={{ font: `12px ${sans}`, color: C.ink }}>{t}</span>
                </button>
              ))}
              <label style={lbl}>Conduct</label>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "7px 0 14px" }}>
                {["Good", "Satisfactory", "Not satisfactory"].map(c => (
                  <button key={c} onClick={() => set("conduct", c)} style={{ cursor: "pointer", border: `1px solid ${f.conduct === c ? C.gold : C.line}`,
                    background: f.conduct === c ? C.goldTint : "#fff", color: f.conduct === c ? C.goldDeep : C.inkSoft, borderRadius: 20, padding: "8px 13px", font: `600 12px ${sans}` }}>{c}</button>
                ))}
              </div>
              <Field label="Wording for the certificate" area hint="What you'd be willing to say to their next employer."
                value={f.wording || ""} onChange={v => set("wording", v)} placeholder="Worked with us from 14 Mar 2020 to 31 Aug 2026 as Purchase Manager. Conduct was good and he left of his own accord." />
              <GoldButton onClick={() => {
                if (!f.reliev || !f.char || !f.conduct || (f.wording || "").trim().length < 20) { toast("Both papers, a conduct rating and real wording", "amber"); return; }
                submit({ relievingLetter: "Signed", characterCertificate: "Signed", conduct: f.conduct, wording: f.wording }, `Papers issued — ${p.name}`);
              }}>Issue the papers</GoldButton>
            </>
          )}

          {isCurrent && view === "closed" && (
            <>
              <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1fr 1fr", gap: 12 }}>
                <div><label style={lbl}>Paid by</label>
                  <select value={f.mode || ""} onChange={e => set("mode", e.target.value)} style={{ ...inp, margin: "7px 0 14px" }}>
                    <option value="">— choose —</option><option>Bank transfer</option><option>Cheque</option><option>Cash</option>
                  </select></div>
                <div><label style={lbl}>Reference</label><input value={f.ref || ""} onChange={e => set("ref", e.target.value)} placeholder="UTR / cheque no." style={{ ...inp, margin: "7px 0 14px" }} /></div>
              </div>
              <button onClick={() => set("ack", !f.ack)} style={{ width: "100%", textAlign: "left", cursor: "pointer",
                border: `1px solid ${f.ack ? C.green : C.line}`, background: f.ack ? C.greenSoft : "#fff", borderRadius: 11, padding: "13px 15px", display: "flex", gap: 11, alignItems: "center", marginBottom: 14 }}>
                <span style={{ width: 22, height: 22, borderRadius: 6, border: `1.5px solid ${f.ack ? C.green : C.line}`, background: f.ack ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}>{f.ack && <Check size={14} color="#fff" />}</span>
                <span>
                  <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>They have signed the acknowledgement</span>
                  <span style={{ display: "block", font: `11px ${sans}`, color: C.stone, marginTop: 2 }}>Received the amount, the papers, and has nothing further outstanding.</span>
                </span>
              </button>
              <GoldButton onClick={() => {
                if (!f.mode || !f.ref || !f.ack) { toast("Payment mode, reference and their signature", "amber"); return; }
                submit({ paidBy: f.mode, reference: f.ref, acknowledged: "Yes", closedOn: nowStamp() }, `Employment ended — ${p.name}`);
                onClose();
              }}>Close this employment</GoldButton>
            </>
          )}
        </div>
      </div>
    </Overlay>
  );
}

function ExitsView() {
  const mob = useIsMobile();
  const { people, exits, openExit, ledger } = useProc();
  const [pick, setPick] = useState(false);
  const [run, setRun] = useState(null);
  const [q, setQ] = useState("");
  const active = people.filter(p => p.status === "active");
  const hits = q.trim() ? active.filter(p => (p.name + p.id + p.designation).toLowerCase().includes(q.toLowerCase())).slice(0, 6) : [];
  const chk = verifyLedger(ledger);
  const running = exits.filter(e => e.stage !== "closed");
  const finished = exits.filter(e => e.stage === "closed");

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Exits</Eyebrow><Pill tone="stone">{running.length} in progress</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Ending an employment, properly.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 660, margin: "0 0 18px", lineHeight: 1.55 }}>
        Six steps, in order. Nothing skips ahead — the card can't be cancelled before the work is handed over,
        and the papers can't be issued before the money is settled.
      </p>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 18 }}>
        <GoldButton onClick={() => setPick(true)}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><LogOut size={15} /> Start a deboarding</span>
        </GoldButton>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, background: chk.ok ? C.greenSoft : C.redSoft,
          border: `1px solid ${chk.ok ? C.green : C.red}`, borderRadius: 20, padding: "8px 14px" }}>
          <ShieldCheck size={15} color={chk.ok ? C.green : C.red} />
          <span style={{ font: `600 12px ${sans}`, color: chk.ok ? C.green : C.red }}>
            {chk.ok ? `Ledger intact — ${chk.count} entries` : `Ledger broken at entry ${chk.index + 1}`}
          </span>
        </div>
      </div>

      <Card pad={mob ? 14 : 18} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
          <History size={15} color={C.goldDeep} /><Eyebrow>The ledger</Eyebrow>
          <span style={{ marginLeft: "auto", font: `11px ${mono}`, color: C.stone }}>head {chk.ok ? chk.head.slice(0, 12) : "\u2014"}</span>
        </div>
        <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginBottom: 12, lineHeight: 1.6 }}>
          Each entry is sealed with a fingerprint of itself plus the one before it. Change any line and every seal
          after it stops matching, and this turns red. <b style={{ color: C.ink }}>It shows tampering. It cannot prevent it</b> —
          that needs a server, and this app runs entirely in your browser.
        </div>
        {ledger.slice(0, 6).map((e, i) => (
          <div key={e.id} style={{ display: "flex", gap: 10, alignItems: "flex-start", padding: "9px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
            <span style={{ font: `10px ${mono}`, color: C.gold, width: 74, flexShrink: 0, wordBreak: "break-all" }}>{e.seal.slice(0, 8)}</span>
            <span style={{ flex: 1, minWidth: 0 }}>
              <span style={{ display: "block", font: `12px ${sans}`, color: C.ink }}>{e.detail}</span>
              <span style={{ display: "block", font: `11px ${sans}`, color: C.stone, marginTop: 2 }}>{e.at} · {e.who}</span>
            </span>
            <Pill tone="stone">{e.kind}</Pill>
          </div>
        ))}
      </Card>

      {running.length > 0 && (
        <div style={{ marginBottom: 16 }}>
          <Eyebrow>In progress</Eyebrow>
          <div style={{ marginTop: 10, display: "grid", gap: 12 }}>
            {running.map(e => {
              const p = people.find(x => x.id === e.pid);
              if (!p) return null;
              const idx = EXIT_STAGES.findIndex(s => s.k === e.stage);
              return (
                <Card key={e.id} pad={mob ? 14 : 18}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12, flexWrap: "wrap" }}>
                    <span style={{ font: `600 15px ${sans}`, color: C.ink }}>{p.name}</span>
                    <Pill tone="stone">{p.designation}</Pill>
                    <Pill tone="amber">{e.record.decision ? e.record.decision.reason : "opening"}</Pill>
                    <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>step {idx + 1} of {EXIT_STAGES.length}</span>
                  </div>
                  <Flowchart stages={EXIT_STAGES} current={e.stage} doneKeys={EXIT_STAGES.map(s => s.k).slice(0, idx)} onPick={() => setRun(e.id)} />
                  <div style={{ marginTop: 12 }}>
                    <GoldButton small onClick={() => setRun(e.id)}>
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>Continue <ArrowRight size={14} /></span>
                    </GoldButton>
                  </div>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {finished.length > 0 && (
        <Card pad={mob ? 14 : 18}>
          <Eyebrow>Closed</Eyebrow>
          {finished.map((e, i) => {
            const p = people.find(x => x.id === e.pid);
            return (
              <div key={e.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
                <CheckCircle2 size={15} color={C.green} />
                <span style={{ flex: 1, font: `600 13px ${sans}`, color: C.ink }}>{p ? p.name : e.pid}</span>
                <span style={{ font: `11px ${sans}`, color: C.stone }}>{e.record.decision ? e.record.decision.reason : ""}</span>
                <button onClick={() => setRun(e.id)} style={{ ...softBtn, padding: "5px 11px" }}>View file</button>
              </div>
            );
          })}
        </Card>
      )}

      {pick && (
        <Overlay onClose={() => setPick(false)} width={480}>
          <div style={{ padding: mob ? 16 : 22 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
              <LogOut size={18} color={C.red} /><Eyebrow color={C.red}>Who is leaving</Eyebrow>
              <button onClick={() => setPick(false)} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
            </div>
            <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="Name or Employee ID" style={{ ...inp, margin: "0 0 12px" }} />
            {/* EDIT 5 of 5: the onClick below is `async` and awaits openExit —
                the exit id is assigned by the server, not made up here. */}
            {hits.map(p => (
              <button key={p.id} onClick={async () => { const id = await openExit(p); setPick(false); setQ(""); if (id) setRun(id); }}
                style={{ width: "100%", textAlign: "left", cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff",
                  borderRadius: 10, padding: "11px 13px", display: "flex", alignItems: "center", gap: 10, marginBottom: 7 }}>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{p.name}</span>
                  <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{p.designation} · {p.id}</span>
                </span>
                <ChevronRight size={16} color={C.stone} />
              </button>
            ))}
            {q.trim() && !hits.length && <div style={{ font: `12px ${sans}`, color: C.stone }}>Nobody matches that.</div>}
          </div>
        </Overlay>
      )}

      {run && (() => {
        const e = exits.find(x => x.id === run);
        const p = e && people.find(x => x.id === e.pid);
        return e && p ? <ExitRunner ex={e} p={p} onClose={() => setRun(null)} /> : null;
      })()}
    </div>
  );
}

/* ============================== COMPANIES · PROJECTS · SCOPE ==============================

   The thing this fixes: "which company is this person actually hired under?"

   A project is a place. A company is the legal entity that signs the contract, pays the
   salary, files the PF and whose letterhead the relieving letter is printed on. They are
   NOT the same. Marbella Grand and Twin Towers are both built by Delhi Punjab Real Estates
   LLP; Curo One and Royce by D.R. Developers & Colonisers. So a storeman posted to Grand is
   employed by the LLP, not by "Grand". Get that wrong and the F&F, the PF challan and the
   experience letter all name the wrong employer.

   Scope: pick "Marbella Group" and every listed project is in view. Pick one and HR sees
   only that one. Companies own projects; projects have their own GSTIN and RERA.

   ON VALIDATION — GSTIN. The shape is checked strictly: 2-digit state code, 10-character
   PAN, entity code, a literal Z, then a check character. That part is certain. The check
   CHARACTER is computed too, but it is only ever shown as a warning, never a block — the
   algorithm here passes some published sample GSTINs and not others, and I would rather
   let a real number through with a flag than reject a supplier's genuine registration on
   the strength of arithmetic I could not fully confirm. Only the GST portal can say for
   certain whether a number is live. Same for RERA: the shape is checked, the registration
   is not.                                                                                  */

const GST_ALPHA = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

const GST_SHAPE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$/;

const GST_STATES = {
  "01": "Jammu & Kashmir", "02": "Himachal Pradesh", "03": "Punjab", "04": "Chandigarh",
  "05": "Uttarakhand", "06": "Haryana", "07": "Delhi", "08": "Rajasthan", "09": "Uttar Pradesh",
  "10": "Bihar", "19": "West Bengal", "22": "Chhattisgarh", "23": "Madhya Pradesh",
  "24": "Gujarat", "27": "Maharashtra", "29": "Karnataka", "32": "Kerala", "33": "Tamil Nadu",
  "36": "Telangana", "37": "Andhra Pradesh",
};

function gstinCheck(raw) {
  const g = String(raw || "").toUpperCase().trim();
  if (!g) return { level: "none" };
  if (!GST_SHAPE.test(g)) return { level: "error", msg: "Not a GSTIN shape — 15 characters: 2 state digits, a 10-character PAN, entity code, Z, check character." };
  let sum = 0;
  for (let i = 0; i < 14; i++) { const p = GST_ALPHA.indexOf(g[i]) * (i % 2 === 0 ? 1 : 2); sum += Math.floor(p / 36) + (p % 36); }
  const expect = GST_ALPHA[(36 - (sum % 36)) % 36];
  const state = GST_STATES[g.slice(0, 2)];
  if (!state) return { level: "warn", msg: `State code ${g.slice(0, 2)} isn't one I recognise. Worth a look.`, pan: g.slice(2, 12) };
  if (expect !== g[14]) return { level: "warn", state, pan: g.slice(2, 12), msg: `Shape is right and the state reads ${state}, but my check character comes out "${expect}" not "${g[14]}". Usually a typo — confirm it on the GST portal before you rely on it.` };
  return { level: "ok", state, pan: g.slice(2, 12), msg: `${state} · PAN ${g.slice(2, 12)} · check character matches.` };
}

const RERA_SHAPE = /^[A-Z]{2}RERA[-\s]?[A-Z0-9]{3,10}[-\s]?[A-Z0-9]{4,12}$/i;

function reraCheck(raw, status) {
  const r = String(raw || "").trim();
  if (status !== "received") return { level: "none" };
  if (!r) return { level: "error", msg: "Marked as received but no number entered." };
  if (!RERA_SHAPE.test(r)) return { level: "warn", msg: "Doesn't look like the usual PBRERA-SAS79-PR0421 pattern. Check it — formats do vary by state." };
  return { level: "ok", msg: "Shape looks right. Only the RERA portal can confirm it's live." };
}

