function suggestJD(designation, dept) {
  const s = String(designation || "").toLowerCase();
  const hit = JD_LIB.find(j => j.match.some(m => s.includes(m)));
  if (hit) return hit;
  const byDept = { Store: 3, Purchase: 4, Security: 5, "Site Engineering": 6, Accounts: 7, Maintenance: 8, HR: 9, Admin: 10, "QA / QC": 11, Labour: 12 }[dept];
  return byDept !== undefined ? JD_LIB[byDept] : JD_LIB[12];
}

/* ============================== THE DESK ==============================
   Everything HR writes, from one place. Pick the person, and the desk already knows who
   employs them, since when, and what's coming up. Pick a letter, fill the few blanks that
   are actually specific to the situation, choose whose letterhead it goes on, and send it.

   Every use is counted. Not to watch anyone — to show which parts of this she actually
   reaches for, so the rest can be fixed or thrown away.                                 */

const MONTHS3 = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

const parseD = (s) => {
  const m = String(s || "").match(/^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$/);
  if (!m) return null;
  const mi = MONTHS3.findIndex(x => x.toLowerCase() === m[2].toLowerCase());
  return mi < 0 ? null : new Date(+m[3], mi, +m[1]);
};

const NOW = new Date(2026, 7, 29);

function tenureOf(joined) {
  const d = parseD(joined); if (!d) return { years: 0, text: "—" };
  let y = NOW.getFullYear() - d.getFullYear(), mo = NOW.getMonth() - d.getMonth();
  if (mo < 0 || (mo === 0 && NOW.getDate() < d.getDate())) { y--; mo += 12; }
  if (NOW.getDate() < d.getDate()) mo--;
  if (mo < 0) mo += 12;
  const parts = [];
  if (y) parts.push(`${y} year${y > 1 ? "s" : ""}`);
  if (mo) parts.push(`${mo} month${mo > 1 ? "s" : ""}`);
  return { years: y, months: mo, text: parts.join(" ") || "less than a month" };
}

function daysToAnniversary(dstr) {
  const d = parseD(dstr); if (!d) return null;
  let next = new Date(NOW.getFullYear(), d.getMonth(), d.getDate());
  if (next < new Date(NOW.getFullYear(), NOW.getMonth(), NOW.getDate())) next = new Date(NOW.getFullYear() + 1, d.getMonth(), d.getDate());
  return Math.round((next - new Date(NOW.getFullYear(), NOW.getMonth(), NOW.getDate())) / 86400000);
}

const prettyToday = () => `${String(NOW.getDate()).padStart(2, "0")} ${MONTHS3[NOW.getMonth()]} ${NOW.getFullYear()}`;

function mergeText(text, vals) {
  return String(text).replace(/\{\{(\w+)\}\}/g, (_, k) => (vals[k] !== undefined && vals[k] !== "" ? vals[k] : `\u2039${k}\u203a`));
}

function Letterhead({ company, project, body, subject, channel }) {
  const mob = useIsMobile();
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12, overflow: "hidden", boxShadow: "0 10px 30px rgba(22,52,95,.10)" }}>
      <div style={{ height: 5, background: `linear-gradient(90deg, ${C.ink}, ${C.gold})` }} />
      <div style={{ padding: mob ? 18 : 28 }}>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 13, borderBottom: `2px solid ${C.ink}`, paddingBottom: 12, marginBottom: 18 }}>
          <img src={CREST} alt="" style={{ height: 42 }} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ font: `700 19px ${serif}`, color: C.ink, lineHeight: 1 }}>Marbella</div>
            <div style={{ font: `700 7px ${sans}`, letterSpacing: ".3em", color: C.goldDeep, marginTop: 4 }}>EMBRACE THE LUXE!</div>
          </div>
          <div style={{ textAlign: "right", font: `10px ${sans}`, color: C.inkSoft, lineHeight: 1.65, maxWidth: 250 }}>
            <div style={{ font: `600 11px ${sans}`, color: C.ink }}>{company ? company.name : "—"}</div>
            <div>{company ? company.addr : ""}</div>
            {company && company.gstin && <div style={{ fontFamily: mono, fontSize: 9 }}>GSTIN {company.gstin}</div>}
            {project && project.reraStatus === "received" && <div style={{ fontFamily: mono, fontSize: 9 }}>RERA {project.rera}</div>}
          </div>
        </div>
        {channel === "email" && subject && (
          <div style={{ background: C.paper, borderRadius: 8, padding: "9px 12px", marginBottom: 16, font: `12px ${sans}`, color: C.inkSoft }}>
            <b style={{ color: C.ink }}>Subject:</b> {subject}
          </div>
        )}
        {channel !== "email" && (
          <div style={{ textAlign: "right", font: `11px ${sans}`, color: C.stone, marginBottom: 16 }}>{prettyToday()}</div>
        )}
        <div style={{ whiteSpace: "pre-wrap", font: `13px/1.85 ${sans}`, color: C.ink }}>{body}</div>
      </div>
    </div>
  );
}

function CorrespondenceView() {
  const mob = useIsMobile();
  const { people, companies, projects, salaries, contacts, track, logDoc, docLog } = useProc();
  const [q, setQ] = useState("");
  const [pid, setPid] = useState(null);
  const [tplId, setTplId] = useState(null);
  const [coId, setCoId] = useState(null);
  const [vals, setVals] = useState({});
  const [bodyEdit, setBodyEdit] = useState(null);
  const [cat, setCat] = useState("all");

  const p = people.find(x => x.id === pid);
  const hits = q.trim() ? people.filter(x => (x.name + " " + x.id + " " + x.designation).toLowerCase().includes(q.trim().toLowerCase())).slice(0, 7) : [];
  const co = p ? (companies.find(c => c.id === (coId || p.employer)) || companies[0]) : null;
  const proj = p ? projects.find(pr => pr.id === p.office) : null;
  const tpl = TEMPLATES.find(t => t.id === tplId);
  const boss = p && people.find(x => x.id === p.reportsTo);
  const ten = p ? tenureOf(p.joined) : null;
  const bdayIn = p && p.dob ? daysToAnniversary(p.dob) : null;
  const annivIn = p ? daysToAnniversary(p.joined) : null;

  const base = p ? {
    name: p.name, first: p.name.split(" ")[0], id: p.id, designation: p.designation, dept: p.dept,
    company: co ? co.name : "", joined: p.joined, tenure: ten.text, years: String(ten.years),
    manager: boss ? `${boss.name} (${boss.designation})` : "your reporting manager",
    today: prettyToday(), hrName: "Simran Kaur", hrTitle: "HR Head", project: proj ? proj.name : "",
  } : {};
  const all = { ...base, ...vals };
  const mergedBody = tpl ? (bodyEdit !== null ? bodyEdit : mergeText(tpl.body, all)) : "";
  const mergedSubj = tpl ? mergeText(tpl.subject, all) : "";
  const blanks = (mergedBody.match(/\u2039\w+\u203a/g) || []).length;

  const suggestions = useMemo(() => {
    if (!p) return [];
    const s = [];
    if (bdayIn !== null && bdayIn <= 14) s.push(["bday", bdayIn === 0 ? "Birthday is today" : `Birthday in ${bdayIn} day${bdayIn > 1 ? "s" : ""}`]);
    if (annivIn !== null && annivIn <= 14 && ten.years >= 1) s.push(["anniv", annivIn === 0 ? `${ten.years + 1} years today` : `${ten.years + 1} years in ${annivIn} day${annivIn > 1 ? "s" : ""}`]);
    if (p.perf >= 90) s.push(["appreciate", `Performance at ${p.perf} — worth saying so`]);
    if (p.perf < 68) s.push(["pip", `Performance at ${p.perf} — below the line`]);
    if (ten.years === 0 && ten.months >= 5 && ten.months <= 8) s.push(["confirm", "Probation window — confirm or extend"]);
    return s;
  }, [p, bdayIn, annivIn]);

  const shown = TEMPLATES.filter(t => cat === "all" || t.cat === cat);
  const reset = () => { setTplId(null); setVals({}); setBodyEdit(null); };

  const doSend = (how) => {
    if (!p || !tpl) return;
    if (blanks) { toast(`${blanks} blank${blanks > 1 ? "s" : ""} left in the letter`, "amber"); return; }
    track(`letter:${tpl.id}`);
    logDoc({ tpl: tpl.id, tplName: tpl.name, pid: p.id, who: p.name, company: co.name, how, subject: mergedSubj });
    toast(how === "email" ? `Sent to ${p.name}` : how === "print" ? "Sent to the printer" : "Saved to their file", "green");
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>The desk</Eyebrow><Pill tone="gold">{TEMPLATES.length} templates</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Everything you write, from one place.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 660, margin: "0 0 18px", lineHeight: 1.55 }}>
        Find the person first. The desk works out who employs them and since when, then fills every letter
        with the right name, the right company and the right dates.
      </p>

      <Card pad={mob ? 14 : 18} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, border: `1.5px solid ${C.gold}`, borderRadius: 12, padding: "11px 14px", background: C.goldTint }}>
          <Search size={18} color={C.goldDeep} />
          <input value={q} onChange={e => { setQ(e.target.value); }} placeholder="Employee ID or name — e.g. MB-PUR-0012"
            style={{ border: "none", outline: "none", background: "transparent", flex: 1, font: `14px ${sans}`, color: C.ink }} />
          {p && <button onClick={() => { setPid(null); setQ(""); reset(); }} style={{ ...softBtn, padding: "5px 11px" }}>Change</button>}
        </div>
        {hits.length > 0 && !p && (
          <div style={{ marginTop: 10 }}>
            {hits.map(h => (
              <button key={h.id} onClick={() => { setPid(h.id); setCoId(h.employer); setQ(h.name); track("desk:pick"); }}
                style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none", background: "#fff", borderRadius: 10,
                  padding: "10px 13px", display: "flex", alignItems: "center", gap: 11, marginBottom: 6, boxShadow: "0 1px 0 rgba(22,52,95,.04)" }}>
                <span style={{ width: 32, height: 32, borderRadius: 9, background: C.goldTint, color: C.goldDeep, display: "grid", placeItems: "center", font: `700 13px ${serif}`, flexShrink: 0 }}>{h.name[0]}</span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{h.name}</span>
                  <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{h.designation} · {h.id}</span>
                </span>
                <ChevronRight size={16} color={C.stone} />
              </button>
            ))}
          </div>
        )}
      </Card>

      {p && (
        <>
          <Card pad={mob ? 14 : 18} style={{ marginBottom: 16, background: `linear-gradient(135deg, ${C.goldTint}, #fff)`, borderColor: C.gold }}>
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "flex-start" }}>
              <div style={{ width: 48, height: 48, borderRadius: 13, background: C.gold, color: "#fff", display: "grid", placeItems: "center", font: `700 20px ${serif}`, flexShrink: 0 }}>{p.name[0]}</div>
              <div style={{ flex: 1, minWidth: 190 }}>
                <div style={{ font: `400 20px ${serif}`, color: C.ink }}>{p.name}</div>
                <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginTop: 3 }}>{p.designation} · {p.dept} · <span style={{ fontFamily: mono, color: C.goldDeep }}>{p.id}</span></div>
                <div style={{ font: `13px ${sans}`, color: C.ink, marginTop: 9, lineHeight: 1.6 }}>
                  Hired under <b>{co ? co.name : "—"}</b> since <b>{p.joined}</b> — that's <b>{ten.text}</b>.
                </div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 9 }}>
                  {boss && <Pill tone="stone">reports to {boss.name}</Pill>}
                  {bdayIn !== null && bdayIn <= 30 && <Pill tone="gold">birthday in {bdayIn}d</Pill>}
                  {annivIn !== null && annivIn <= 30 && <Pill tone="gold">{ten.years + 1} yrs in {annivIn}d</Pill>}
                  <Pill tone={p.perf >= 85 ? "green" : p.perf >= 70 ? "amber" : "red"}>performance {p.perf}</Pill>
                </div>
              </div>
              <div style={{ minWidth: 190 }}>
                <label style={lbl}>Write on whose letterhead</label>
                <select value={coId || p.employer} onChange={e => { setCoId(e.target.value); setBodyEdit(null); }} style={{ ...inp, margin: "6px 0 0", fontSize: 12 }}>
                  {companies.map(c => <option key={c.id} value={c.id}>{c.name}{c.id === p.employer ? "  (their employer)" : ""}</option>)}
                </select>
                {coId && coId !== p.employer && (
                  <div style={{ font: `11px ${sans}`, color: C.amber, marginTop: 6, display: "flex", gap: 5, lineHeight: 1.5 }}>
                    <TriangleAlert size={12} style={{ flexShrink: 0, marginTop: 2 }} />
                    They're on {companies.find(c => c.id === p.employer).name}'s payroll. Writing from another entity is fine for a courtesy note, wrong for anything contractual.
                  </div>
                )}
              </div>
            </div>
            {suggestions.length > 0 && (
              <div style={{ marginTop: 14, paddingTop: 12, borderTop: `1px solid ${C.gold}44` }}>
                <div style={{ font: `600 10px ${sans}`, letterSpacing: ".12em", textTransform: "uppercase", color: C.goldDeep, marginBottom: 8 }}>Might be worth sending</div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {suggestions.map(([id, why]) => (
                    <button key={id} onClick={() => { reset(); setTplId(id); track("desk:suggested"); }}
                      style={{ cursor: "pointer", border: `1px solid ${C.gold}`, background: "#fff", borderRadius: 20, padding: "7px 13px", font: `600 12px ${sans}`, color: C.ink }}>
                      {TEMPLATES.find(t => t.id === id).name} <span style={{ color: C.stone, fontWeight: 400 }}>· {why}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </Card>

          {!tpl && (
            <>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
                <button onClick={() => setCat("all")} style={{ cursor: "pointer", border: `1px solid ${cat === "all" ? C.ink : C.line}`, background: cat === "all" ? C.ink : "#fff", color: cat === "all" ? "#fff" : C.inkSoft, borderRadius: 20, padding: "7px 14px", font: `600 12px ${sans}` }}>All</button>
                {Object.entries(TPL_CATS).map(([k, v]) => {
                  const on = cat === k; const Ic = v.icon;
                  const col = v.tone === "green" ? C.green : v.tone === "gold" ? C.goldDeep : v.tone === "amber" ? C.amber : v.tone === "red" ? C.red : C.stone;
                  return (
                    <button key={k} onClick={() => setCat(k)} style={{ cursor: "pointer", border: `1px solid ${on ? col : C.line}`, background: on ? "#fff" : "#fff",
                      color: on ? col : C.inkSoft, borderRadius: 20, padding: "7px 13px", font: `600 12px ${sans}`, display: "inline-flex", alignItems: "center", gap: 6,
                      boxShadow: on ? `0 0 0 1px ${col}` : "none" }}><Ic size={13} /> {v.label}</button>
                  );
                })}
              </div>
              <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "repeat(auto-fill, minmax(250px, 1fr))", gap: 12 }}>
                {shown.map(t => {
                  const cc = TPL_CATS[t.cat]; const Ic = cc.icon;
                  const col = cc.tone === "green" ? C.green : cc.tone === "gold" ? C.goldDeep : cc.tone === "amber" ? C.amber : cc.tone === "red" ? C.red : C.stone;
                  return (
                    <button key={t.id} onClick={() => { reset(); setTplId(t.id); track("desk:template"); }}
                      style={{ cursor: "pointer", textAlign: "left", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 12, padding: 15,
                        borderTop: `3px solid ${col}`, boxShadow: "0 1px 2px rgba(34,64,106,.04)" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
                        <Ic size={15} color={col} />
                        <span style={{ font: `600 13px ${sans}`, color: C.ink }}>{t.name}</span>
                        <span style={{ marginLeft: "auto" }}><Pill tone="stone">{t.channel}</Pill></span>
                      </div>
                      <div style={{ font: `11px ${sans}`, color: C.stone, lineHeight: 1.55 }}>{t.when}</div>
                    </button>
                  );
                })}
              </div>
            </>
          )}

          {tpl && (
            <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "360px 1fr", gap: 18, alignItems: "start" }}>
              <div>
                <Card pad={mob ? 14 : 18}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                    <Eyebrow>{tpl.name}</Eyebrow>
                    <button onClick={reset} style={{ marginLeft: "auto", ...softBtn, padding: "5px 11px" }}>Other letter</button>
                  </div>
                  <div style={{ font: `12px ${sans}`, color: C.stone, margin: "8px 0 14px", lineHeight: 1.55 }}>{tpl.when}</div>
                  {tpl.fields.length ? tpl.fields.map(([k, label, eg]) => (
                    <div key={k} style={{ marginBottom: 12 }}>
                      <label style={lbl}>{label}</label>
                      <textarea rows={String(eg).length > 60 ? 3 : 1} value={vals[k] || ""} onChange={e => { setVals(v => ({ ...v, [k]: e.target.value })); setBodyEdit(null); }}
                        placeholder={eg} style={{ ...inp, margin: "6px 0 0", resize: "vertical", fontSize: 13 }} />
                    </div>
                  )) : <div style={{ font: `12px ${sans}`, color: C.stone }}>Nothing to fill in — this one writes itself.</div>}
                  {tpl.fields.length > 0 && (
                    <button onClick={() => { const v = {}; tpl.fields.forEach(([k, , eg]) => v[k] = mergeText(eg, base)); setVals(v); setBodyEdit(null); toast("Filled with the example wording — edit it", "gold"); }}
                      style={{ ...softBtn, marginTop: 4 }}>Use the example wording</button>
                  )}
                </Card>

                <Card pad={mob ? 14 : 18} style={{ marginTop: 14 }}>
                  <Eyebrow>Send it</Eyebrow>
                  {blanks > 0 && (
                    <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 9, padding: "9px 12px", margin: "10px 0", font: `12px ${sans}`, color: "#6E4E12", display: "flex", gap: 7 }}>
                      <TriangleAlert size={14} style={{ flexShrink: 0, marginTop: 1 }} />
                      {blanks} blank{blanks > 1 ? "s" : ""} still showing in the letter — they're marked ‹like this›.
                    </div>
                  )}
                  <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10 }}>
                    {tpl.channel === "email" && <GreenButton small onClick={() => doSend("email")}><Send size={14} /> Email it</GreenButton>}
                    <GoldButton small onClick={() => doSend("print")}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Printer size={14} /> Print</span></GoldButton>
                    <GoldButton small ghost onClick={() => doSend("file")}>Save to file</GoldButton>
                  </div>
                  <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10, lineHeight: 1.55 }}>
                    Emailing needs a mail service connected — that's a backend step. Everything else here is real: the merge,
                    the letterhead, and the record that it went out.
                  </div>
                </Card>
              </div>

              <div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                  <Eyebrow>Preview</Eyebrow>
                  <button onClick={() => setBodyEdit(bodyEdit === null ? mergedBody : null)} style={{ marginLeft: "auto", ...softBtn, padding: "5px 11px", display: "inline-flex", alignItems: "center", gap: 6 }}>
                    <Pencil size={12} /> {bodyEdit === null ? "Edit the wording" : "Back to the template"}
                  </button>
                </div>
                {bodyEdit !== null ? (
                  <textarea value={bodyEdit} onChange={e => setBodyEdit(e.target.value)} rows={26}
                    style={{ ...inp, margin: 0, font: `13px/1.8 ${sans}`, resize: "vertical" }} />
                ) : (
                  <Letterhead company={co} project={proj} body={mergedBody} subject={mergedSubj} channel={tpl.channel} />
                )}
              </div>
            </div>
          )}
        </>
      )}

      {!p && docLog.length > 0 && (
        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <History size={15} color={C.goldDeep} /><Eyebrow>Recently sent</Eyebrow>
          </div>
          {docLog.slice(0, 8).map((d, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", flexWrap: "wrap" }}>
              <span style={{ flex: 1, minWidth: 150 }}>
                <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{d.tplName} — {d.who}</span>
                <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{d.company} · {d.at}</span>
              </span>
              <Pill tone={d.how === "email" ? "green" : d.how === "print" ? "gold" : "stone"}>{d.how}</Pill>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function JDView() {
  const mob = useIsMobile();
  const { people, jds, saveJD, track } = useProc();
  const active = people.filter(p => p.status === "active");
  const roles = useMemo(() => {
    const m = {};
    active.forEach(p => { const k = p.designation + "\u0001" + p.dept; m[k] = (m[k] || 0) + 1; });
    return Object.entries(m).map(([k, n]) => { const [designation, dept] = k.split("\u0001"); return { designation, dept, n }; })
      .sort((a, b) => b.n - a.n);
  }, [active]);
  const [sel, setSel] = useState(null);
  const [draft, setDraft] = useState(null);
  const cur = sel ? roles.find(r => r.designation === sel.designation && r.dept === sel.dept) : null;
  const saved = sel ? jds[sel.designation] : null;
  const sug = sel ? suggestJD(sel.designation, sel.dept) : null;

  const open = (r) => {
    setSel(r); track("jd:open");
    const s = jds[r.designation] || suggestJD(r.designation, r.dept);
    setDraft({ purpose: s.purpose, duties: [...s.duties], needs: [...s.needs] });
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Job descriptions</Eyebrow><Pill tone="stone">{roles.length} distinct roles</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>What each job is actually for.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 660, margin: "0 0 18px", lineHeight: 1.55 }}>
        Pick a role and the desk drafts a description from what that job does on our sites. It's a starting point,
        not gospel — edit it until it reads like the job you actually need doing, then save it.
      </p>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "300px 1fr", gap: 18, alignItems: "start" }}>
        <Card pad={mob ? 12 : 14}>
          <Eyebrow>Roles on the roster</Eyebrow>
          <div style={{ maxHeight: 520, overflowY: "auto", marginTop: 10 }}>
            {roles.map(r => {
              const on = sel && sel.designation === r.designation && sel.dept === r.dept;
              const has = !!jds[r.designation];
              return (
                <button key={r.designation + r.dept} onClick={() => open(r)}
                  style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none", background: on ? C.goldTint : "transparent",
                    borderRadius: 9, padding: "9px 11px", display: "flex", alignItems: "center", gap: 9, marginBottom: 3 }}>
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ display: "block", font: `600 12px ${sans}`, color: C.ink }}>{r.designation}</span>
                    <span style={{ display: "block", font: `10px ${sans}`, color: C.stone }}>{r.dept}</span>
                  </span>
                  {has && <Check size={13} color={C.green} />}
                  <span style={{ font: `700 12px ${mono}`, color: C.stone }}>{r.n}</span>
                </button>
              );
            })}
          </div>
        </Card>

        <div>
          {!sel && <Card pad={26}><div style={{ textAlign: "center", color: C.stone, font: `13px ${sans}` }}>Pick a role on the left.</div></Card>}
          {sel && draft && (
            <Card pad={mob ? 16 : 22}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4, flexWrap: "wrap" }}>
                <Eyebrow>{sel.dept}</Eyebrow>
                <Pill tone="stone">{cur ? cur.n : 0} in this role</Pill>
                {saved ? <Pill tone="green">saved</Pill> : <Pill tone="gold">suggested</Pill>}
              </div>
              <h2 style={{ font: `400 22px ${serif}`, margin: "6px 0 16px", color: C.ink }}>{sel.designation}</h2>

              <label style={lbl}>What this job is for</label>
              <textarea rows={2} value={draft.purpose} onChange={e => setDraft(d => ({ ...d, purpose: e.target.value }))} style={{ ...inp, margin: "7px 0 16px", fontSize: 13 }} />

              <label style={lbl}>What they do</label>
              <div style={{ marginTop: 7, marginBottom: 8 }}>
                {draft.duties.map((d, i) => (
                  <div key={i} style={{ display: "flex", gap: 8, alignItems: "flex-start", marginBottom: 7 }}>
                    <span style={{ width: 6, height: 6, borderRadius: "50%", background: C.gold, marginTop: 13, flexShrink: 0 }} />
                    <textarea rows={1} value={d} onChange={e => setDraft(x => { const a = [...x.duties]; a[i] = e.target.value; return { ...x, duties: a }; })}
                      style={{ ...inp, margin: 0, fontSize: 13, resize: "vertical" }} />
                    <button onClick={() => setDraft(x => ({ ...x, duties: x.duties.filter((_, j) => j !== i) }))}
                      style={{ background: "none", border: "none", cursor: "pointer", color: C.stone, marginTop: 10 }}><X size={14} /></button>
                  </div>
                ))}
                <button onClick={() => setDraft(x => ({ ...x, duties: [...x.duties, ""] }))} style={{ ...softBtn, marginTop: 2 }}>+ Add a duty</button>
              </div>

              <label style={lbl}>What they need to be</label>
              <div style={{ marginTop: 7, marginBottom: 16 }}>
                {draft.needs.map((d, i) => (
                  <div key={i} style={{ display: "flex", gap: 8, alignItems: "flex-start", marginBottom: 7 }}>
                    <span style={{ width: 6, height: 6, borderRadius: "50%", background: C.ink, marginTop: 13, flexShrink: 0 }} />
                    <textarea rows={1} value={d} onChange={e => setDraft(x => { const a = [...x.needs]; a[i] = e.target.value; return { ...x, needs: a }; })}
                      style={{ ...inp, margin: 0, fontSize: 13, resize: "vertical" }} />
                    <button onClick={() => setDraft(x => ({ ...x, needs: x.needs.filter((_, j) => j !== i) }))}
                      style={{ background: "none", border: "none", cursor: "pointer", color: C.stone, marginTop: 10 }}><X size={14} /></button>
                  </div>
                ))}
                <button onClick={() => setDraft(x => ({ ...x, needs: [...x.needs, ""] }))} style={{ ...softBtn, marginTop: 2 }}>+ Add a requirement</button>
              </div>

              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <GoldButton onClick={() => { saveJD(sel.designation, draft); track("jd:save"); toast(`Job description saved — ${sel.designation}`, "green"); }}>Save this description</GoldButton>
                <button onClick={() => { const s = suggestJD(sel.designation, sel.dept); setDraft({ purpose: s.purpose, duties: [...s.duties], needs: [...s.needs] }); toast("Back to the suggestion", "stone"); }} style={softBtn}>Start over</button>
              </div>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

function UsageView() {
  const mob = useIsMobile();
  const { usage, docLog, cardLog, exits, ledger, people } = useProc();
  const rows = Object.entries(usage).map(([k, n]) => ({ k, n })).sort((a, b) => b.n - a.n);
  const total = rows.reduce((a, r) => a + r.n, 0);
  const NICE = {
    "desk:pick": "Looked someone up on the desk", "desk:template": "Opened a letter template",
    "desk:suggested": "Used a suggested letter", "jd:open": "Opened a job description",
    "jd:save": "Saved a job description", "card:issue": "Issued an ID card",
    "import:run": "Ran a bulk import", "exit:step": "Advanced a deboarding",
    "org:explore": "Explored the org tree", "project:save": "Added or edited a project",
  };
  const nice = (k) => NICE[k] || (k.startsWith("letter:") ? `Sent: ${(TEMPLATES.find(t => t.id === k.slice(7)) || {}).name || k.slice(7)}` : k);
  const modules = [
    ["The desk", docLog.length, "letters written"],
    ["Card bureau", cardLog.length, "cards issued"],
    ["Exits", exits.length, "deboardings run"],
    ["Ledger", ledger.length, "sealed entries"],
    ["Roster", people.filter(p => p.status === "active").length, "people on file"],
  ];
  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Usage</Eyebrow><Pill tone="stone">{total} actions recorded</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>What's actually being used.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 660, margin: "0 0 18px", lineHeight: 1.55 }}>
        Not a watch on anybody. A count of which parts of this get reached for, so the parts that don't can be
        fixed or taken out. Counts reset when the app reloads — persisting them is a backend job.
      </p>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(5,1fr)", gap: 12, marginBottom: 18 }}>
        {modules.map(([k, v, sub]) => (
          <Card key={k} pad={14}>
            <div style={{ font: `700 26px ${mono}`, color: v ? C.ink : C.stone }}>{v}</div>
            <div style={{ font: `600 11px ${sans}`, color: C.ink, marginTop: 4 }}>{k}</div>
            <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 2 }}>{sub}</div>
          </Card>
        ))}
      </div>

      <Card pad={mob ? 14 : 18}>
        <Eyebrow>Every action, most used first</Eyebrow>
        {rows.length ? rows.map((r, i) => (
          <div key={r.k} style={{ padding: "9px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span style={{ flex: 1, font: `13px ${sans}`, color: C.ink }}>{nice(r.k)}</span>
              <span style={{ font: `700 14px ${mono}`, color: C.ink }}>{r.n}</span>
            </div>
            <div style={{ height: 5, background: C.lineSoft, borderRadius: 3, marginTop: 5, overflow: "hidden" }}>
              <div style={{ width: `${(r.n / rows[0].n) * 100}%`, height: "100%", background: C.gold }} />
            </div>
          </div>
        )) : <div style={{ font: `13px ${sans}`, color: C.stone, marginTop: 10 }}>Nothing yet — use the desk and it'll show up here.</div>}
      </Card>
    </div>
  );
}

/* ============================== THE ORG, WITH DEPTH ==============================
   Honest about what this is: CSS 3D perspective, not a WebGL model. Real transforms —
   the cards genuinely sit on different Z planes, tilt with the scene and parallax as you
   drag. I chose this over three.js deliberately: a name and a designation have to stay
   crisp at every angle, and text in a WebGL scene does not. You get the depth without
   losing the legibility, and it runs on a site office phone.                            */

const DEPT_HUE = {
  Admin: "#224A85", HR: "#7B4B8A", Purchase: "#8A6224", Store: "#3E7C55", Accounts: "#1F6F7A",
  "Site Engineering": "#B0603C", Maintenance: "#5B6B8C", Security: "#8A2B3B", "QA / QC": "#2F6E4E", Labour: "#7A6A4F",
};

const hueOf = (d) => DEPT_HUE[d] || C.stone;

function OrgCard({ p, all, depth, tilt, onOpen, selected, expanded, toggle, reveal, dept }) {
  /* `all` is ALWAYS the full list — structure and headcounts are computed from reality,
     never from a filtered slice. A department filter only decides what is SHOWN. */
  if (reveal && !reveal.has(p.id)) return null;
  const kids = all.filter(x => x.reportsTo === p.id && x.id !== p.id);
  const dim = !!dept && p.dept !== dept;
  const open = expanded.includes(p.id);
  const [hover, setHover] = useState(false);
  const hue = hueOf(p.dept);
  const team = (() => { const seen = new Set(); const walk = (id) => all.filter(x => x.reportsTo === id && x.id !== id).forEach(c => { if (!seen.has(c.id)) { seen.add(c.id); walk(c.id); } }); walk(p.id); return seen.size; })();
  const on = selected === p.id;
  const z = Math.max(0, 60 - depth * 16) + (hover ? 34 : 0) + (on ? 24 : 0);

  return (
    <div style={{ transformStyle: "preserve-3d", marginTop: depth ? 9 : 0 }}>
      <div
        onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
        onClick={(e) => { e.stopPropagation(); onOpen(p.id); }}
        style={{
          transformStyle: "preserve-3d", transform: `translateZ(${z}px)`, transition: "transform .3s cubic-bezier(.2,.8,.2,1), box-shadow .3s",
          cursor: "pointer", position: "relative",
          background: on ? `linear-gradient(135deg, ${hue}, ${hue}CC)` : "#fff",
          color: on ? "#fff" : C.ink,
          border: `1px solid ${on ? hue : C.line}`, borderLeft: `4px solid ${hue}`,
          borderRadius: 12, padding: "11px 13px",
          boxShadow: on ? `0 ${18 + depth * 2}px ${34}px ${hue}55, 0 2px 0 ${hue}`
                        : `0 ${6 + (hover ? 12 : 0)}px ${14 + (hover ? 20 : 0)}px rgba(22,52,95,${0.10 + (hover ? 0.1 : 0)})`,
          minWidth: 240, opacity: dim ? 0.5 : 1,
        }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ width: 34, height: 34, borderRadius: 10, background: on ? "rgba(255,255,255,.22)" : hue + "1A",
            color: on ? "#fff" : hue, display: "grid", placeItems: "center", font: `700 14px ${serif}`, flexShrink: 0,
            transform: "translateZ(14px)", boxShadow: hover ? `0 4px 10px ${hue}44` : "none" }}>{p.name[0]}</span>
          <span style={{ flex: 1, minWidth: 0 }}>
            <span style={{ display: "block", font: `600 13px ${sans}`, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.name}</span>
            <span style={{ display: "block", font: `10.5px ${sans}`, color: on ? "rgba(255,255,255,.8)" : C.stone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.designation}</span>
          </span>
          {team > 0 && (
            <span title={`${team} people beneath ${p.name} in total (${kids.length} report directly)`}
              style={{ transform: "translateZ(18px)", font: `700 10px ${mono}`, letterSpacing: ".04em",
              background: on ? "rgba(255,255,255,.2)" : C.goldTint, color: on ? "#fff" : C.goldDeep,
              borderRadius: 20, padding: "4px 8px", flexShrink: 0 }}>{team}</span>
          )}
          {kids.length > 0 && (
            <button onClick={(e) => { e.stopPropagation(); toggle(p.id); }}
              style={{ background: "none", border: "none", cursor: "pointer", color: on ? "#fff" : C.stone, display: "grid", placeItems: "center", flexShrink: 0, transform: "translateZ(18px)" }}>
              <ChevronRight size={16} style={{ transform: open ? "rotate(90deg)" : "none", transition: "transform .2s" }} />
            </button>
          )}
        </div>
      </div>

      {open && kids.length > 0 && (
        <div style={{ transformStyle: "preserve-3d", marginLeft: 26, paddingLeft: 16, borderLeft: `1.5px solid ${hue}44` }}>
          {kids.map(k => <OrgCard key={k.id} p={k} all={all} depth={depth + 1} tilt={tilt} onOpen={onOpen} selected={selected} expanded={expanded} toggle={toggle} reveal={reveal} dept={dept} />)}
        </div>
      )}
    </div>
  );
}

function OrgView() {
  const mob = useIsMobile();
  const { people, companies, projects, scope, track, jds } = useProc();
  const inScope = (p) => scope === "group" || p.office === scope;
  const active = people.filter(p => p.status === "active" && inScope(p));
  const isRoot = (p) => !p.reportsTo || p.reportsTo === p.id || !active.some(x => x.id === p.reportsTo);
  const roots = active.filter(isRoot);
  const [expanded, setExpanded] = useState(() => people.filter(p => !p.reportsTo || p.reportsTo === p.id).map(p => p.id));
  const [sel, setSel] = useState(null);
  const [tilt, setTilt] = useState({ x: 12, y: -8 });
  const [drag, setDrag] = useState(null);
  const [dept, setDept] = useState("all");
  const toggle = (id) => setExpanded(e => e.includes(id) ? e.filter(x => x !== id) : [...e, id]);
  const open = (id) => { setSel(id); track("org:explore"); };

  const p = sel && active.find(x => x.id === sel);
  const boss = p && active.find(x => x.id === p.reportsTo);
  const kids = p ? active.filter(x => x.reportsTo === p.id && x.id !== p.id) : [];
  const co = p && companies.find(c => c.id === p.employer);
  const ten = p ? tenureOf(p.joined) : null;
  const jd = p ? (jds[p.designation] || suggestJD(p.designation, p.dept)) : null;

  const chain = (() => {
    if (!p) return [];
    const out = []; let cur = p, guard = 0;
    while (cur && guard++ < 20) { out.unshift(cur); const nx = active.find(x => x.id === cur.reportsTo); if (!nx || nx.id === cur.id) break; cur = nx; }
    return out;
  })();

  /* everyone in the chosen department, plus every manager above them, so the line stays whole */
  const reveal = useMemo(() => {
    if (dept === "all") return null;
    const byId = {}; active.forEach(x => byId[x.id] = x);
    const set = new Set();
    active.filter(x => x.dept === dept).forEach(x => {
      let cur = x, guard = 0;
      while (cur && guard++ < 25) { set.add(cur.id); const up = byId[cur.reportsTo]; if (!up || up.id === cur.id) break; cur = up; }
    });
    return set;
  }, [dept, active]);
  const inDept = dept === "all" ? 0 : active.filter(x => x.dept === dept).length;
  useEffect(() => { if (reveal) setExpanded(e => [...new Set([...e, ...reveal])]); }, [dept]);

  const deptCounts = useMemo(() => {
    const m = {}; active.forEach(x => m[x.dept] = (m[x.dept] || 0) + 1);
    return Object.entries(m).sort((a, b) => b[1] - a[1]);
  }, [active]);

  const onDown = (e) => setDrag({ x: e.clientX, y: e.clientY, tx: tilt.x, ty: tilt.y });
  const onMove = (e) => { if (!drag) return; setTilt({ x: Math.max(-6, Math.min(26, drag.tx + (e.clientY - drag.y) * 0.12)), y: Math.max(-24, Math.min(24, drag.ty + (e.clientX - drag.x) * 0.12)) }); };
  const onUp = () => setDrag(null);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Organisation</Eyebrow><Pill tone="stone">{active.length} people</Pill>
        {scope !== "group" && <Pill tone="gold">{(projects.find(x => x.id === scope) || {}).short}</Pill>}
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Who reports to whom.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 640, margin: "0 0 14px", lineHeight: 1.55 }}>
        Drag the board to turn it. Click anyone to open their card. The strip down each card is their department, and the number on the right is how many people sit beneath them in total.
      </p>
      <ScopeBar />

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14, alignItems: "center" }}>
        {deptCounts.map(([d, n]) => (
          <button key={d} onClick={() => setDept(dept === d ? "all" : d)}
            style={{ cursor: "pointer", border: `1px solid ${dept === d ? hueOf(d) : C.line}`, background: dept === d ? hueOf(d) : "#fff",
              color: dept === d ? "#fff" : C.inkSoft, borderRadius: 20, padding: "6px 12px", font: `600 11px ${sans}`,
              display: "inline-flex", alignItems: "center", gap: 6 }}>
            <span style={{ width: 7, height: 7, borderRadius: "50%", background: dept === d ? "#fff" : hueOf(d) }} />{d} <b style={{ fontFamily: mono }}>{n}</b>
          </button>
        ))}
        {dept !== "all" && (
          <span style={{ font: `11px ${sans}`, color: C.inkSoft, display: "inline-flex", alignItems: "center", gap: 6 }}>
            <Info size={12} color={hueOf(dept)} />
            {inDept} in {dept} — their managers are shown faded to keep the line unbroken.
          </span>
        )}
        <button onClick={() => { setTilt({ x: 12, y: -8 }); toast("Board reset", "stone"); }} style={{ ...softBtn, marginLeft: "auto", padding: "6px 12px" }}>Straighten up</button>
        <button onClick={() => setExpanded(expanded.length > roots.length ? roots.map(r => r.id) : active.map(a => a.id))} style={{ ...softBtn, padding: "6px 12px" }}>
          {expanded.length > roots.length ? "Collapse" : "Expand all"}
        </button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1.35fr 1fr", gap: 18, alignItems: "start" }}>
        <div
          onMouseDown={onDown} onMouseMove={onMove} onMouseUp={onUp} onMouseLeave={onUp}
          onClick={() => setSel(null)}
          style={{ perspective: 1500, perspectiveOrigin: "50% 30%", padding: mob ? "20px 8px" : "34px 22px",
            background: `radial-gradient(120% 90% at 50% 0%, ${C.panel}, ${C.paper})`,
            border: `1px solid ${C.line}`, borderRadius: 16, overflow: "auto", maxHeight: 620,
            cursor: drag ? "grabbing" : "grab", userSelect: "none",
            boxShadow: "inset 0 2px 18px rgba(22,52,95,.06)" }}>
          <div style={{ transformStyle: "preserve-3d", transform: `rotateX(${tilt.x}deg) rotateY(${tilt.y}deg)`, transition: drag ? "none" : "transform .5s cubic-bezier(.2,.8,.2,1)" }}>
            {roots.length ? roots.map(r => (
              <OrgCard key={r.id} p={r} all={active} depth={0} tilt={tilt} onOpen={open}
                selected={sel} expanded={expanded} toggle={toggle}
                reveal={dept === "all" ? null : reveal} dept={dept === "all" ? null : dept} />
            )) : <div style={{ font: `13px ${sans}`, color: C.stone, textAlign: "center", padding: 30 }}>Nobody in this view.</div>}
          </div>
        </div>

        <div>
          {!p && (
            <Card pad={mob ? 16 : 20}>
              <Eyebrow>Biggest teams</Eyebrow>
              <div style={{ marginTop: 12 }}>
                {active.map(x => ({ x, n: active.filter(y => y.reportsTo === x.id && y.id !== x.id).length }))
                  .filter(v => v.n > 0).sort((a, b) => b.n - a.n).slice(0, 8).map(({ x, n }, i, arr) => (
                  <div key={x.id} style={{ padding: "8px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <span style={{ width: 8, height: 8, borderRadius: "50%", background: hueOf(x.dept), flexShrink: 0 }} />
                      <span style={{ flex: 1, minWidth: 0 }}>
                        <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{x.name}</span>
                        <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{x.designation}</span>
                      </span>
                      <span style={{ font: `700 15px ${mono}`, color: C.ink }}>{n}</span>
                    </div>
                    <div style={{ height: 5, background: C.lineSoft, borderRadius: 3, marginTop: 5, overflow: "hidden" }}>
                      <div style={{ width: `${(n / arr[0].n) * 100}%`, height: "100%", background: hueOf(x.dept) }} />
                    </div>
                  </div>
                ))}
              </div>
              <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 14, lineHeight: 1.55 }}>Click a card on the board to open someone.</div>
            </Card>
          )}

          {p && (
            <Card pad={mob ? 16 : 20} style={{ borderTop: `4px solid ${hueOf(p.dept)}` }}>
              <div style={{ display: "flex", alignItems: "flex-start", gap: 12, marginBottom: 14 }}>
                <div style={{ width: 46, height: 46, borderRadius: 13, background: hueOf(p.dept), color: "#fff", display: "grid", placeItems: "center", font: `700 19px ${serif}`, flexShrink: 0 }}>{p.name[0]}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ font: `400 20px ${serif}`, color: C.ink }}>{p.name}</div>
                  <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginTop: 2 }}>{p.designation}</div>
                  <div style={{ font: `11px ${mono}`, color: C.goldDeep, marginTop: 3 }}>{p.id}</div>
                </div>
                <button onClick={() => setSel(null)} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={17} /></button>
              </div>

              <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginBottom: 14 }}>
                <Pill tone="stone">{p.dept}</Pill>
                <Pill tone="stone">{officeById(p.office).short}</Pill>
                <Pill tone="gold">{ten.text} in</Pill>
                <Pill tone={p.perf >= 85 ? "green" : p.perf >= 70 ? "amber" : "red"}>perf {p.perf}</Pill>
                {kids.length > 0 && <Pill tone="gold">{kids.length} report directly</Pill>}
                {(() => { const seen = new Set(); const walk = (id) => active.filter(x => x.reportsTo === id && x.id !== id).forEach(c => { if (!seen.has(c.id)) { seen.add(c.id); walk(c.id); } }); walk(p.id);
                  return seen.size > kids.length ? <Pill tone="stone">{seen.size} beneath in total</Pill> : null; })()}
              </div>

              <div style={{ background: C.paper, borderRadius: 10, padding: "11px 13px", marginBottom: 14, font: `12px ${sans}`, color: C.inkSoft, lineHeight: 1.7 }}>
                <div>Employed by <b style={{ color: C.ink }}>{co ? co.name : "—"}</b></div>
                <div>Joined <b style={{ color: C.ink }}>{p.joined}</b></div>
                {boss && <div>Reports to <b style={{ color: C.ink }}>{boss.name}</b> · {boss.designation}</div>}
              </div>

              {chain.length > 1 && (
                <div style={{ marginBottom: 14 }}>
                  <div style={{ font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, marginBottom: 7 }}>Line to the top</div>
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
                    {chain.map((c, i) => (
                      <React.Fragment key={c.id}>
                        <button onClick={() => open(c.id)} style={{ cursor: "pointer", border: `1px solid ${c.id === p.id ? hueOf(c.dept) : C.line}`,
                          background: c.id === p.id ? hueOf(c.dept) : "#fff", color: c.id === p.id ? "#fff" : C.inkSoft,
                          borderRadius: 20, padding: "5px 11px", font: `600 11px ${sans}` }}>{c.name}</button>
                        {i < chain.length - 1 && <ChevronRight size={12} color={C.stone} />}
                      </React.Fragment>
                    ))}
                  </div>
                </div>
              )}

              {kids.length > 0 && (
                <div style={{ marginBottom: 14 }}>
                  <div style={{ font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, marginBottom: 7 }}>Reports directly</div>
                  <div style={{ maxHeight: 170, overflowY: "auto" }}>
                    {kids.map(k => (
                      <button key={k.id} onClick={() => open(k.id)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none",
                        background: "transparent", padding: "7px 0", display: "flex", alignItems: "center", gap: 9 }}>
                        <span style={{ width: 7, height: 7, borderRadius: "50%", background: hueOf(k.dept), flexShrink: 0 }} />
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ display: "block", font: `600 12px ${sans}`, color: C.ink }}>{k.name}</span>
                          <span style={{ display: "block", font: `10px ${sans}`, color: C.stone }}>{k.designation}</span>
                        </span>
                        <ChevronRight size={14} color={C.stone} />
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {jd && (
                <div style={{ borderTop: `1px solid ${C.lineSoft}`, paddingTop: 12, marginBottom: 14 }}>
                  <div style={{ font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, marginBottom: 6 }}>
                    What this job is for {jds[p.designation] ? <Pill tone="green">saved</Pill> : <Pill tone="gold">suggested</Pill>}
                  </div>
                  <div style={{ font: `12px ${sans}`, color: C.inkSoft, lineHeight: 1.6 }}>{jd.purpose}</div>
                </div>
              )}

              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <GoldButton small onClick={() => toast(`Open the desk and search ${p.id} to write to ${p.name.split(" ")[0]}`, "gold")}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Mail size={13} /> Write to them</span>
                </GoldButton>
                <button onClick={() => { setExpanded(e => [...new Set([...e, ...chain.map(c => c.id)])]); toast("Opened their line on the board", "stone"); }} style={softBtn}>Show on board</button>
              </div>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

