const HR_NAV = [
  ["home",      "HR Desk",          LayoutGrid],
  ["desk",      "The desk",         Mail],
  ["population","Population",       Users],
  ["org",       "Org chart",        Building2],
  ["cards",     "Card bureau",      ScanFace],
  ["intake",    "Bulk intake",      Upload],
  ["companies", "Companies",        Crown],
  ["jd",        "Job descriptions", ClipboardList],
  ["deptrules", "Working hours",    CalendarClock],
  ["exits",     "Exits & F&F",      LogOut],
  ["usage",     "Usage",            TrendingUp],
];

function HomeView({ go }) {
  const mob = useIsMobile();
  const { people, companies, projects, cardLog, exits, ledger, docLog, contacts } = useProc();
  const active = people.filter(p => p.status === "active");
  const chk = verifyLedger(ledger);
  const soon = active.map(p => ({ p, d: p.dob ? daysToAnniversary(p.dob) : null, kind: "birthday" }))
    .concat(active.map(p => ({ p, d: daysToAnniversary(p.joined), kind: "anniversary" })))
    .filter(x => x.d !== null && x.d <= 10).sort((a, b) => a.d - b.d).slice(0, 6);
  const noContact = active.filter(p => !(contacts[p.id] || {}).phone).length;
  const noPhoto = active.filter(p => !p.photo).length;
  const openExits = exits.filter(e => e.stage !== "closed").length;

  const Tile = ({ k, v, sub, tone, onClick }) => (
    <button onClick={onClick} style={{ cursor: onClick ? "pointer" : "default", textAlign: "left", border: `1px solid ${C.line}`,
      background: C.panel, borderRadius: 14, padding: 16, boxShadow: "0 1px 2px rgba(34,64,106,.04)" }}>
      <div style={{ font: `700 28px ${mono}`, color: tone || C.ink }}>{v}</div>
      <div style={{ font: `600 12px ${sans}`, color: C.ink, marginTop: 4 }}>{k}</div>
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 2 }}>{sub}</div>
    </button>
  );

  return (
    <div>
      <Eyebrow>HR Desk</Eyebrow>
      <h1 style={{ font: `400 26px ${serif}`, margin: "6px 0 4px" }}>Good day, Simran.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, margin: "0 0 18px" }}>
        {active.length} people across {companies.length} companies and {projects.length} projects.
      </p>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(5,1fr)", gap: 12, marginBottom: 18 }}>
        <Tile k="On the rolls" v={active.length} sub="active employees" onClick={() => go("population")} />
        <Tile k="Cards issued" v={cardLog.length} sub="all time" onClick={() => go("cards")} />
        <Tile k="Letters sent" v={docLog.length} sub="from the desk" onClick={() => go("desk")} />
        <Tile k="Exits running" v={openExits} sub="not yet closed" tone={openExits ? C.amber : C.stone} onClick={() => go("exits")} />
        <Tile k="Ledger" v={ledger.length} sub={chk.ok ? "seals intact" : "SEAL BROKEN"} tone={chk.ok ? C.green : C.red} onClick={() => go("exits")} />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1.2fr 1fr", gap: 16 }}>
        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <PartyPopper size={15} color={C.goldDeep} /><Eyebrow>Coming up in the next 10 days</Eyebrow>
          </div>
          {soon.length ? soon.map((x, i) => (
            <div key={x.p.id + x.kind} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
              <span style={{ width: 30, height: 30, borderRadius: 9, background: C.goldTint, color: C.goldDeep, display: "grid", placeItems: "center", font: `700 12px ${serif}`, flexShrink: 0 }}>{x.p.name[0]}</span>
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{x.p.name}</span>
                <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{x.p.designation}</span>
              </span>
              <Pill tone="gold">{x.kind} {x.d === 0 ? "today" : `in ${x.d}d`}</Pill>
            </div>
          )) : <div style={{ font: `13px ${sans}`, color: C.stone, marginTop: 10 }}>Nothing in the next ten days.</div>}
          <div style={{ marginTop: 12 }}><GoldButton small onClick={() => go("desk")}>Open the desk</GoldButton></div>
        </Card>

        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
            <TriangleAlert size={15} color={C.amber} /><Eyebrow color={C.amber}>Needs your attention</Eyebrow>
          </div>
          {[[noContact, "without a personal number", "population", noContact > 0],
            [noPhoto, "without a photo on file", "population", noPhoto > 0],
            [companies.filter(c => !c.gstin).length, "companies with no GSTIN", "companies", companies.some(c => !c.gstin)],
            [projects.filter(p => p.reraStatus === "notyet").length, "projects not RERA registered", "companies", projects.some(p => p.reraStatus === "notyet")]]
            .filter(r => r[3]).map(([n, t, tab], i) => (
            <button key={t} onClick={() => go(tab)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none", background: "transparent",
              padding: "9px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", display: "flex", alignItems: "center", gap: 10 }}>
              <span style={{ font: `700 16px ${mono}`, color: C.amber, width: 34 }}>{n}</span>
              <span style={{ flex: 1, font: `12px ${sans}`, color: C.ink }}>{t}</span>
              <ChevronRight size={15} color={C.stone} />
            </button>
          ))}
          {noContact === 0 && noPhoto === 0 && <div style={{ font: `13px ${sans}`, color: C.green }}>Nothing outstanding.</div>}
        </Card>
      </div>
    </div>
  );
}

